// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"c1-esterase-inhibitor-human":{"wirkmechanismus":"Ersetzt ein Eiweiss im Blut, das beim erblichen (hereditären) Angioödem fehlt oder nicht richtig funktioniert. Der C1-Esterase-Inhibitor hemmt Enzyme des Komplement- und des Kontaktsystems, insbesondere Plasmakallikrein und Faktor XIIa. Fehlt er, entsteht übermässig Bradykinin, das die Gefässe durchlässig macht und die typischen Schwellungen von Haut, Schleimhäuten, Darm und Kehlkopf auslöst. Die Zufuhr hebt die C1-INH-Aktivität an und bremst die Bradykininbildung.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle bei Injektion unter die Haut (Schmerz, Schwellung, Rötung, Bluterguss)"],"haeufig":["Kopfschmerzen","Schwindel","Übelkeit","Hautausschlag","Nasopharyngitis (Erkältungssymptome)"],"gelegentlich":["Venenentzündung (Phlebitis) und Venenthrombose","Fieber","Juckreiz, Hautrötung"],"selten":["Überempfindlichkeitsreaktionen bis Anaphylaxie"]},"schwangerschaft":"Bisherige Erfahrungen ohne Hinweise auf schädliche Wirkungen; Anwendung, wenn klar notwendig (HAE-Attacken können in der Schwangerschaft gefährlich sein).","stillzeit":"Ein Risiko für den Säugling ist nicht zu erwarten; Anwendung nach ärztlicher Abwägung.","hinweise":["Nach Schulung kann das Mittel zu Hause selbst gespritzt werden; die Chargennummer jeder Packung notieren.","Bei Schwellungen im Hals- oder Kehlkopfbereich trotz Injektion sofort den Notfall aufsuchen.","Impfungen gegen Hepatitis A und B mit der Ärztin oder dem Arzt besprechen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (in die Vene)","Pulver und Lösungsmittel zur Injektion unter die Haut"]},"cabergolin":{"wirkmechanismus":"Senkt die Menge des Hormons Prolaktin, das die Milchbildung anregt und bei Überschuss Zyklusstörungen, Unfruchtbarkeit und Libidoverlust verursacht. Cabergolin ist ein lang wirksamer Agonist an Dopamin-D2-Rezeptoren der prolaktinbildenden Zellen der Hirnanhangdrüse (Hypophyse) und hemmt dort die Prolaktinausschüttung; Prolaktinome können dabei schrumpfen. Wegen der sehr langen Halbwertszeit genügt meist eine Einnahme ein- bis zweimal pro Woche. Als Mutterkorn-(Ergolin-)Abkömmling stimuliert es auch Serotonin-5-HT2B-Rezeptoren, was mit Fibrosen und Herzklappenveränderungen in Verbindung gebracht wird.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schwindel","Bauchschmerzen, Verdauungsbeschwerden (Dyspepsie), Magenschleimhautentzündung","Schwäche und Müdigkeit","Herzklappenveränderungen (Valvulopathie) und verwandte Störungen wie Herzbeutelentzündung oder -erguss"],"haeufig":["Depression","Schläfrigkeit (Somnolenz)","Verstopfung, Erbrechen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Hitzewallungen","Brustschmerzen (Mastodynie)"],"gelegentlich":["Herzklopfen (Palpitationen)","Ohnmacht (Synkope), Kribbeln (Parästhesien)","Vorübergehende Gesichtsfeldausfälle","Atemnot, Pleuraerguss (Flüssigkeit im Brustfellraum), Lungenfibrose","Nasenbluten","Krämpfe der Fingergefässe (Vasospasmus)","Haarausfall, Hautausschlag","Wassereinlagerungen (Ödeme)","Wadenkrämpfe","Überempfindlichkeitsreaktionen, gesteigerte Libido"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, gesteigerter Sexualtrieb, Essattacken)","Plötzliches Einschlafen im Alltag","Halluzinationen, Wahnvorstellungen, psychotische Störungen, Aggression","Angina pectoris","Zittern (Tremor), Sehstörungen","Erhöhte Leberwerte und CK"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Kinderwunsch Cabergolin vorsorglich etwa einen Monat vor der geplanten Empfängnis absetzen; tritt unter der Behandlung eine Schwangerschaft ein, ärztlich über das Absetzen entscheiden. Die bisherigen Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Cabergolin unterdrückt die Milchbildung. Frauen, die stillen möchten, dürfen es nicht einnehmen; bei Behandlung einer Hyperprolaktinämie nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen – das vermindert Übelkeit und Schwindel.","Bei Langzeitbehandlung vor Beginn und regelmässig einen Herzultraschall machen lassen; Atemnot, anhaltenden Husten, Brust- oder Flankenschmerzen und Beinödeme ärztlich abklären.","Kann Schläfrigkeit, plötzliches Einschlafen und Blutdruckabfall verursachen – Vorsicht beim Autofahren, besonders in den ersten Tagen.","Auf Spielsucht, Kaufsucht, gesteigerten Sexualtrieb oder Essattacken achten und Angehörige darüber informieren."],"darreichung":["Tabletten"]},"calcifediol":{"wirkmechanismus":"Liefert direkt die Speicherform von Vitamin D, sodass der Vitamin-D-Spiegel rascher und verlässlicher ansteigt. Calcifediol ist 25-Hydroxy-Vitamin-D3, das sonst erst in der Leber aus Colecalciferol gebildet wird. In der Niere und anderen Geweben wird es durch die 1-alpha-Hydroxylase (CYP27B1) zum aktiven Hormon Calcitriol umgewandelt. Calcitriol fördert die Aufnahme von Calcium und Phosphat aus dem Darm, unterstützt die Mineralisierung der Knochen und bremst die Ausschüttung von Parathormon. Die Retardform gibt den Wirkstoff langsam ab und vermeidet starke Spiegelspitzen.","nebenwirkungen":{"unbekannt":["Hyperkalzämie (erhöhtes Calcium) mit Übelkeit, Erbrechen, Verstopfung, Durst, vermehrtem Wasserlassen und Müdigkeit","Hyperkalziurie (vermehrt Calcium im Urin), Nierensteine, Nierenverkalkung","Hyperphosphatämie (erhöhtes Phosphat)","Herzrhythmusstörungen bei stark erhöhtem Calcium","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; eine Überdosierung mit erhöhtem Calcium kann dem Kind schaden.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung und ohne zusätzliche Vitamin-D-Gabe an das Kind ohne Rücksprache.","hinweise":["Calcium-, Phosphat- und Vitamin-D-Werte regelmässig kontrollieren lassen.","Keine weiteren Vitamin-D-Präparate ohne ärztliche Rücksprache einnehmen.","Retardkapseln unzerkaut schlucken.","Anhaltende Übelkeit, starker Durst, vermehrtes Wasserlassen oder Verstopfung ärztlich abklären lassen (Zeichen erhöhter Calciumwerte)."],"darreichung":["Retardkapseln"]},"calcipotriol":{"wirkmechanismus":"Bremst das zu schnelle Wachstum der Hautzellen bei Schuppenflechte und normalisiert ihre Reifung. Calcipotriol ist ein synthetischer Abkömmling des aktiven Vitamin D3 (Calcitriol) und bindet an den Vitamin-D-Rezeptor der Hornzellen (Keratinozyten). Dadurch hemmt es deren Vermehrung, fördert eine normale Verhornung und dämpft entzündliche Signale. Seine Wirkung auf den Calciumhaushalt ist etwa 100-mal schwächer als die von Calcitriol; bei zu grossen Mengen kann der Calciumspiegel im Blut trotzdem steigen.","nebenwirkungen":{"haeufig":["Juckreiz","Hautreizung, Brennen, Stechen oder Schmerzen der Haut","Rötung, trockene Haut, Hautausschlag"],"gelegentlich":["Ekzem, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis"],"selten":["Hyperkalzämie (erhöhter Calciumspiegel im Blut) und vermehrte Calciumausscheidung im Urin"],"unbekannt":["Überempfindlichkeitsreaktionen wie Nesselsucht, Angioödem, Schwellung um die Augen oder im Gesicht","Lichtempfindlichkeit der Haut","Hautentzündung im Gesicht oder um den Mund (wenn Salbe dorthin gelangt)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Erfahrungen beim Menschen fehlen; in Tierversuchen traten nach hohen Dosen zum Einnehmen schädliche Wirkungen auf.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen.","hinweise":["Höchstmenge beachten: Erwachsene höchstens 100 g Salbe pro Woche (bei Kombination mit Lösung entsprechend weniger); bei grossflächiger Anwendung kann der Arzt den Calciumspiegel kontrollieren.","Nach dem Auftragen Hände waschen; nicht ins Gesicht oder in die Augen bringen.","Übermässige Sonne und Solarium während der Behandlung meiden."],"darreichung":["Salbe","Lösung zur Anwendung auf der Kopfhaut"]},"calcipotriol-betamethason":{"wirkmechanismus":"Verbindet zwei Wirkprinzipien gegen Schuppenflechte. Calcipotriol, ein Abkömmling von Vitamin D3, bindet an den Vitamin-D-Rezeptor der Hornzellen, bremst deren übermässige Vermehrung und normalisiert die Verhornung. Betamethasondipropionat ist ein stark wirksames Glukokortikoid (Klasse III), das über den Glukokortikoid-Rezeptor Entzündung, Rötung und Juckreiz unterdrückt. Die Kombination wirkt schneller und stärker als jeder Wirkstoff allein, und das Kortison mildert die Hautreizung durch Calcipotriol.","nebenwirkungen":{"haeufig":["Juckreiz"],"gelegentlich":["Brennen, Reizung oder Schmerzen der Haut","Rötung, Ausschlag, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis","Hautinfektionen (Bakterien, Pilze, Viren), Haarbalgentzündung (Follikulitis)","Pigmentveränderungen an der Anwendungsstelle"],"selten":["Hautatrophie (Verdünnung der Haut), Dehnungsstreifen (Striae)","Pustulöse Psoriasis","Überempfindlichkeitsreaktionen, Nesselsucht","Rebound-Effekt (Wiederaufflammen nach dem Absetzen)","Hyperkalzämie (erhöhter Calciumspiegel im Blut)"],"unbekannt":["Verschwommenes Sehen","Vorübergehende gelbliche Verfärbung weisser oder grauer Haare (Gel auf der Kopfhaut)","Unterdrückung der Nebennierenrinde bei grossflächiger Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Daten fehlen, und Kortison wirkte in Tierversuchen fruchtschädigend.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht auf die Brust auftragen.","hinweise":["Höchstmengen beachten: höchstens 15 g pro Tag und 100 g pro Woche, nicht mehr als 30 % der Körperoberfläche.","Nach dem Auftragen Hände waschen; nicht ins Gesicht, in die Augen oder auf Schleimhäute bringen und nicht unter luftdichten Verbänden anwenden.","Der Schaum ist leicht entzündlich: beim Auftragen nicht rauchen und offene Flammen meiden."],"darreichung":["Salbe","Gel","Schaum zur Anwendung auf der Haut"]},"calcitriol":{"wirkmechanismus":"Ist die fertige, aktive Form von Vitamin D und muss – anders als gewöhnliches Vitamin D – nicht erst in Leber und Niere umgewandelt werden. Calcitriol (1,25-Dihydroxycholecalciferol) bindet an den Vitamin-D-Rezeptor und steigert dadurch die Aufnahme von Calcium und Phosphat aus dem Darm, die Rückresorption von Calcium in der Niere und die Mineralisierung des Knochens; zudem hemmt es die Bildung von Parathormon. Deshalb wirkt es auch, wenn die kranke Niere selbst kein aktives Vitamin D mehr bilden kann. Auf der Haut hemmt es die übermässige Vermehrung der Hornzellen (Keratinozyten) und fördert deren normale Ausreifung.","nebenwirkungen":{"sehrHaeufig":["Hyperkalzämie (erhöhtes Calcium im Blut) bei Einnahme der Kapseln"],"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit","Hautausschlag","Harnwegsinfekte","Salbe: Hautreizung, Rötung und Juckreiz an der behandelten Stelle"],"gelegentlich":["Appetitlosigkeit, Erbrechen","Anstieg des Kreatinins im Blut"],"unbekannt":["Zeichen einer Hyperkalzämie: Durst, vermehrtes Wasserlassen, Verstopfung, Muskelschwäche, Teilnahmslosigkeit","Kalkablagerungen in Geweben (Calcinose) und Nierensteine bei anhaltender Hyperkalzämie","Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht)","Wachstumsverzögerung bei Kindern mit anhaltender Hyperkalzämie"]},"schwangerschaft":"Nur bei klarer Notwendigkeit und unter Kontrolle des Calciums, da eine Hyperkalzämie der Mutter dem Kind schaden kann; die Salbe nur nach ärztlicher Abwägung und kleinflächig.","stillzeit":"Calcitriol geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung mit Kontrolle des Calciums bei Mutter und Kind.","hinweise":["Blutkontrollen (Calcium, Phosphat, Kreatinin) zuverlässig wahrnehmen, besonders zu Beginn und nach Dosisänderungen.","Keine weiteren Vitamin-D- oder Calciumpräparate ohne ärztliche Absprache einnehmen; ausreichend trinken.","Warnzeichen zu hohen Calciums (starker Durst, viel Wasserlassen, Übelkeit, Verstopfung, Muskelschwäche, Verwirrtheit) ärztlich melden.","Salbe dünn auftragen und danach die Hände waschen."],"darreichung":["Weichkapseln","Salbe"]},"calcium":{"wirkmechanismus":"Ersetzt Calcium, das für Knochen und Zähne sowie für Muskeln, Nerven, Herz und Blutgerinnung unentbehrlich ist. Rund 99 % des Körpercalciums sind im Knochen gespeichert; eine ausreichende Zufuhr bremst den Knochenabbau, besonders zusammen mit Vitamin D, das die Aufnahme im Darm steigert. Calciumcarbonat braucht für die Aufnahme Magensäure und wird zu den Mahlzeiten besser aufgenommen, Calciumcitrat unabhängig davon. Intravenös gegebenes Calcium hebt einen gefährlich tiefen Calciumspiegel innert Minuten an.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Injektion: Wärmegefühl, Hitzewallung, Blutdruckabfall, langsamer Puls oder Rhythmusstörungen bei zu rascher Gabe","Injektion: Reizung oder Gewebeschäden an der Einstichstelle"]},"schwangerschaft":"In üblichen Dosen erlaubt, der Bedarf ist erhöht; hohe Dosen und eine Hyperkalzämie vermeiden.","stillzeit":"Erlaubt; Calcium geht in die Muttermilch über.","hinweise":["Calciumcarbonat am besten zu den Mahlzeiten einnehmen; Kautabletten kauen oder lutschen, Brausetabletten in Wasser auflösen.","Abstand zu Antibiotika (Tetracycline, Chinolone), Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Lebensmittel mit viel Oxalsäure (Spinat, Rhabarber) oder Phytinsäure (Vollkorn) vermindern die Calciumaufnahme."],"darreichung":["Kautabletten","Brausetabletten","Lutschtabletten","Injektionslösung (Calciumgluconat)"]},"calcium-colecalciferol":{"wirkmechanismus":"Liefert gleichzeitig Calcium und Vitamin D3, die der Knochen für seine Festigkeit braucht. Vitamin D3 wird in Leber und Niere zu Calcitriol aktiviert und steigert die Aufnahme von Calcium im Darm; das Calcium wird in den Knochen eingebaut. Gemeinsam gleichen sie einen Mangel aus und senken das Parathormon, das bei Mangel den Knochenabbau antreibt (sekundärer Hyperparathyreoidismus). So wird der altersbedingte Knochenabbau gebremst.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Überempfindlichkeitsreaktionen wie Angioödem oder Kehlkopfschwellung"]},"schwangerschaft":"Bei Bedarf in üblichen Dosen erlaubt; in der Schwangerschaft insgesamt nicht mehr als 2500 mg Calcium und 4000 I. E. Vitamin D pro Tag aufnehmen.","stillzeit":"Erlaubt; Calcium und Vitamin D gehen in die Muttermilch über – bei zusätzlicher Vitamin-D-Gabe an den Säugling berücksichtigen.","hinweise":["Kautabletten kauen oder lutschen, am besten nach einer Mahlzeit.","Abstand zu Tetracyclinen, Chinolonen, Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Keine weiteren Calcium- oder Vitamin-D-Präparate ohne ärztliche Absprache einnehmen."],"darreichung":["Kautabletten","Lutschtabletten","Brausetabletten"]},"calciumcarbonat-magnesiumcarbonat":{"wirkmechanismus":"Neutralisiert überschüssige Magensäure und lindert Sodbrennen innert Minuten. Calciumcarbonat und Magnesiumcarbonat reagieren mit der Salzsäure im Magen zu Calcium- bzw. Magnesiumchlorid, Wasser und Kohlendioxid und heben so den pH-Wert des Mageninhalts an. Magnesium wirkt leicht abführend, Calcium eher verstopfend. Ein Teil des Calciums und Magnesiums wird ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Juckreiz, Anaphylaxie)","Übelkeit, Erbrechen, Magenbeschwerden","Durchfall oder Verstopfung","Hyperkalzämie und Alkalose bei langer, hochdosierter Einnahme (Milch-Alkali-Syndrom)","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Muskelschwäche als Zeichen eines erhöhten Calcium- oder Magnesiumspiegels"]},"schwangerschaft":"Kann in der Schwangerschaft in der empfohlenen Dosis kurzfristig angewendet werden; eine übermässige Calciumzufuhr (zusätzlich viel Milch oder Calciumpräparate) vermeiden.","stillzeit":"In der empfohlenen Dosierung möglich.","hinweise":["Tabletten bei Bedarf lutschen oder kauen; Tageshöchstdosis gemäss Packungsbeilage nicht überschreiten.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Kau- und Lutschtabletten"]},"calciumdobesilat":{"wirkmechanismus":"Stärkt die Wände kleiner Blutgefässe und vermindert Schwellungen. Calciumdobesilat senkt die erhöhte Durchlässigkeit der Kapillaren, verbessert die Fliesseigenschaften des Blutes (geringere Viskosität und Plättchenzusammenlagerung) und wirkt antioxidativ. Dadurch tritt weniger Flüssigkeit ins Gewebe aus.","nebenwirkungen":{"sehrSelten":["Agranulozytose (starker Mangel an weissen Blutkörperchen) mit Fieber und Infektionen"],"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Durchfall)","Hautreaktionen (Ausschlag, Juckreiz)","Fieber, Schüttelfrost","Gelenkschmerzen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Bei Fieber, Halsschmerzen, Mundschleimhautentzündung oder anderen Infektzeichen sofort ärztlich melden und das Blutbild kontrollieren lassen.","Während der Mahlzeiten einnehmen.","Vor Blutuntersuchungen die Einnahme angeben (kann die Kreatininmessung verfälschen)."],"darreichung":["Kapseln"]},"canagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren mehr Zucker mit dem Urin ausscheiden. Canagliflozin hemmt den Natrium-Glucose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glucose zurück ins Blut holt. Die Wirkung ist unabhängig vom Insulin; zusätzlich gehen Kalorien sowie etwas Salz und Wasser verloren, was Gewicht und Blutdruck leicht senkt. Bei eingeschränkter Nierenfunktion lässt die blutzuckersenkende Wirkung nach.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoffen","Pilzinfektion der Scheide"],"haeufig":["Pilzinfektion oder Entzündung der Eichel (Balanitis)","Harnwegsinfekte","Vermehrtes Wasserlassen","Durst","Obstipation (Verstopfung), Übelkeit","Veränderte Blutfettwerte, erhöhter Hämatokrit"],"gelegentlich":["Flüssigkeitsmangel mit Schwindel beim Aufstehen, tiefem Blutdruck oder Ohnmacht","Hautausschlag, Nesselsucht","Knochenbrüche","Akutes Nierenversagen","Amputationen der unteren Gliedmassen (vor allem Zehen)"],"selten":["Diabetische Ketoazidose","Anaphylaxie, Angioödem"],"unbekannt":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)"]},"schwangerschaft":"Nicht anwenden; im Tierversuch wurden die sich entwickelnden Nieren geschädigt (entspricht dem 2. und 3. Schwangerschaftsdrittel). In der Schwangerschaft wird Insulin verwendet.","stillzeit":"Nicht anwenden.","hinweise":["Auf gute Intimhygiene achten; bei Juckreiz, Ausfluss oder Rötung im Genitalbereich ärztlichen Rat einholen.","Vor grösseren Operationen und bei akuten Erkrankungen mit Erbrechen, Durchfall oder Fasten nach ärztlicher Anweisung pausieren.","Bei Übelkeit, Erbrechen, Bauchschmerzen, starkem Durst oder Atemnot sofort ärztlich abklären lassen – eine Ketoazidose ist auch bei normalem Blutzucker möglich.","Füsse täglich kontrollieren; Wunden oder Druckstellen früh behandeln lassen."],"darreichung":["Filmtabletten"]},"candesartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Candesartancilexetil wird bei der Aufnahme im Darm vollständig zu Candesartan aktiviert, das sehr fest und lang anhaltend an den AT1-Rezeptor bindet. Dadurch weiten sich die Gefässe, die Aldosteronausschüttung sinkt und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Candesartan wird kaum verstoffwechselt und über Niere und Galle ausgeschieden; Reizhusten ist selten, da der Bradykinin-Abbau nicht beeinflusst wird.","nebenwirkungen":{"haeufig":["Atemwegsinfektionen","Schwindel, Drehschwindel","Kopfschmerzen","Hypotonie (tiefer Blutdruck) – vor allem bei Herzschwäche","Hyperkaliämie (erhöhtes Kalium) – vor allem bei Herzschwäche","Nierenfunktionsstörung, Kreatininanstieg – vor allem bei Herzschwäche"],"sehrSelten":["Leukopenie, Neutropenie, Agranulozytose (Mangel an weissen Blutkörperchen)","Hyponatriämie (Natriummangel)","Husten","Übelkeit","Erhöhte Leberwerte, Hepatitis","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Hautausschlag, Nesselsucht, Juckreiz","Rücken-, Gelenk- und Muskelschmerzen","Nierenversagen bei empfindlichen Patienten"],"unbekannt":["Durchfall"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"capecitabin":{"wirkmechanismus":"Wird erst im Körper, bevorzugt im Tumorgewebe, in den eigentlichen Wirkstoff Fluorouracil (5-FU) umgewandelt. Die Aktivierung erfolgt in drei Schritten über Carboxylesterase und Cytidin-Deaminase (Leber) sowie Thymidin-Phosphorylase, die in vielen Tumoren vermehrt vorkommt. Fluorouracil hemmt die Thymidylat-Synthase und damit die DNA-Synthese und wird fehlerhaft in die RNA eingebaut. Der Abbau erfolgt über das Enzym DPD; bei DPD-Mangel drohen schwere Vergiftungen.","nebenwirkungen":{"sehrHaeufig":["Hand-Fuss-Syndrom (Rötung, Schwellung, Schmerzen an Handflächen und Fusssohlen)","Durchfall","Übelkeit, Erbrechen","Mundschleimhautentzündung (Stomatitis)","Bauchschmerzen","Appetitlosigkeit","Müdigkeit, Schwäche"],"haeufig":["Neutropenie, Anämie","Infektionen (z. B. Herpes)","Flüssigkeitsmangel, Gewichtsverlust","Kopfschmerzen, Schwindel, Geschmacksstörung, Kribbeln","Tränende, gereizte Augen, Bindehautentzündung","Erhöhtes Bilirubin, veränderte Leberwerte","Hautausschlag, Haarausfall, Hautverfärbung","Fieber, Wassereinlagerungen, Brustschmerzen"],"gelegentlich":["Thrombozytopenie, Fieber bei Neutropenie","Angina pectoris, Herzinfarkt, Herzrhythmusstörungen","Thrombosen und Lungenembolie","Magen-Darm-Blutungen, Darmverschluss","Lichtempfindlichkeit, Nesselsucht","Periphere Neuropathie (Nervenschäden)","Überempfindlichkeitsreaktionen"],"selten":["QT-Verlängerung, Kammerflimmern, Torsade de pointes","Verengung der Tränenwege, Hornhautentzündung","Leberversagen, cholestatische Hepatitis","Angioödem","Kutaner Lupus erythematodes"],"sehrSelten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse"],"unbekannt":["Toxische Leukenzephalopathie (Schädigung der weissen Hirnsubstanz)","Akutes Nierenversagen bei Flüssigkeitsmangel"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Frauen müssen während und bis 6 Monate nach der letzten Dosis zuverlässig verhüten, Männer mit Partnerin im gebärfähigen Alter bis 3 Monate danach.","stillzeit":"Kontraindiziert; während und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Tabletten innerhalb von 30 Minuten nach einer Mahlzeit mit Wasser unzerkaut schlucken.","Vor Behandlungsbeginn wird auf einen DPD-Mangel getestet.","Bei Durchfall (mehr als 4 zusätzliche Stühle pro Tag), Erbrechen, Mundgeschwüren, Fieber oder schmerzhaften Händen und Füssen Einnahme unterbrechen und sofort ärztlich melden.","Kein Brivudin (Gürtelrosemittel) während der Behandlung sowie in den 4 Wochen davor und danach; bei Blutverdünnern INR engmaschig kontrollieren."],"darreichung":["Filmtabletten"]},"carbamazepin":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen und verhindert so Krampfanfälle und einschiessende Nervenschmerzen. Carbamazepin blockiert spannungsabhängige Natriumkanäle und hemmt dadurch die wiederholte, hochfrequente Entladung von Nervenzellen. Es wird über CYP3A4 zum ebenfalls wirksamen Carbamazepin-10,11-epoxid abgebaut und ist selbst ein starker Induktor von CYP3A4, weiteren CYP-Enzymen und P-Glykoprotein – auch seines eigenen Abbaus (Autoinduktion).","nebenwirkungen":{"sehrHaeufig":["Leukopenie (Mangel an weissen Blutkörperchen)","Schwindel, Gang- und Koordinationsstörungen (Ataxie), Schläfrigkeit","Übelkeit, Erbrechen","Allergische Hautreaktionen, Nesselsucht","Erhöhte Gamma-GT (Leberenzym)"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen), Eosinophilie","Hyponatriämie (Natriummangel), Wassereinlagerungen, Gewichtszunahme","Kopfschmerzen, Müdigkeit","Doppelbilder, verschwommenes Sehen","Mundtrockenheit","Erhöhte alkalische Phosphatase"],"gelegentlich":["Unwillkürliche Bewegungen (Zittern, Tics, Dystonie), Augenzittern (Nystagmus)","Durchfall, Verstopfung","Erhöhte Leberwerte (Transaminasen)","Exfoliative Dermatitis (schuppende Hautentzündung)"],"selten":["Multiorgan-Überempfindlichkeitsreaktion (DRESS) mit Fieber, Ausschlag und Organbeteiligung","Hepatitis, Gelbsucht","Herzrhythmusstörungen, AV-Block","Halluzinationen, Depression, Verwirrtheit, Unruhe","Lupus-erythematodes-ähnliches Syndrom","Periphere Nervenschädigung, Sprechstörungen"],"sehrSelten":["Agranulozytose, aplastische Anämie, Panzytopenie (schwere Blutbildstörungen)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie, Angioödem","Leberversagen","Pankreatitis (Entzündung der Bauchspeicheldrüse)","Akute Porphyrie","Interstitielle Nephritis, Nierenversagen","Verminderte Knochendichte (Osteomalazie)"],"unbekannt":["Knochenmarkdepression","Kolitis (Darmentzündung)","Reaktivierung des Herpesvirus 6","Knochenbrüche"]},"schwangerschaft":"Erhöht das Risiko für Fehlbildungen (u. a. Neuralrohrdefekte); nicht ohne ärztliche Rücksprache absetzen. Bei Kinderwunsch Behandlung vorab überprüfen; Monotherapie in niedrigster wirksamer Dosis und Folsäure-Einnahme.","stillzeit":"Geht in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind auf Schläfrigkeit, Trinkschwäche und Hautausschlag beobachten.","hinweise":["Blutbild, Leberwerte und Natrium vor und regelmässig während der Behandlung kontrollieren; bei Fieber, Halsschmerzen, Ausschlag, Blutergüssen oder Gelbsucht sofort ärztlich melden.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Vor jedem neuen Medikament (auch Pille, Antibiotika, Blutverdünner) auf Carbamazepin hinweisen: viele Wechselwirkungen.","Kein Grapefruitsaft; Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Tabletten","Retardtabletten","Suspension zum Einnehmen"]},"carbetocin":{"wirkmechanismus":"Bewirkt, dass sich die Gebärmutter nach der Geburt zusammenzieht, und beugt so starken Blutungen vor. Carbetocin ist ein synthetisches, lang wirksames Analogon des Hormons Oxytocin und bindet an die Oxytocin-Rezeptoren der Gebärmuttermuskulatur. Innerhalb von etwa 2 Minuten setzen kräftige Kontraktionen ein, die rund eine Stunde anhalten – länger als nach Oxytocin. Eine einmalige Injektion genügt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Bauchschmerzen","Juckreiz","Kopfschmerzen","Zittern","Blutdruckabfall","Flush (Gesichtsrötung), Wärmegefühl"],"haeufig":["Erbrechen","Rückenschmerzen","Schwindel","Metallischer Geschmack","Anämie (Blutarmut)","Brustschmerzen","Atemnot","Schüttelfrost"]},"schwangerschaft":"Vor der Geburt des Kindes kontraindiziert; nicht zur Geburtseinleitung oder Wehenverstärkung.","stillzeit":"Nur sehr geringe Mengen gehen in die Muttermilch über und werden im Darm des Säuglings abgebaut; Stillen ist möglich.","hinweise":["Wird einmalig nach der Entbindung des Kindes von Fachpersonen in die Vene gespritzt; keine Wiederholung.","Blutdruck und Blutungen werden danach überwacht.","Bei anhaltender Blutung müssen andere Ursachen abgeklärt werden."],"darreichung":["Injektionslösung"]},"carbimazol":{"wirkmechanismus":"Bremst die Bildung von Schilddrüsenhormonen und normalisiert so den Stoffwechsel bei einer Überfunktion. Carbimazol wird im Körper rasch und vollständig in den Wirkstoff Thiamazol (Methimazol) umgewandelt. Thiamazol hemmt die Thyreoperoxidase, das Enzym, das Jod in das Speichereiweiss Thyreoglobulin einbaut und die Hormonvorstufen zu T4 und T3 verknüpft. Bereits gebildetes, gespeichertes Hormon wird nicht beeinflusst; deshalb setzt die Wirkung erst nach 1–3 Wochen ein, die volle Wirkung oft erst nach 4–8 Wochen.","nebenwirkungen":{"haeufig":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gelenkschmerzen","Übelkeit, leichte Magen-Darm-Beschwerden","Kopfschmerzen"],"gelegentlich":["Agranulozytose (starker Mangel an weissen Blutkörperchen) mit Fieber, Halsschmerzen und Infektionen, meist in den ersten Behandlungsmonaten","Arzneimittelfieber"],"sehrSelten":["Leberschäden (Gallenstau mit Gelbsucht, Hepatitis)","Aplastische Anämie, Thrombozytopenie, Panzytopenie (Mangel an allen Blutzellen)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Haarausfall","Insulin-Autoimmunsyndrom mit Unterzuckerung","Vaskulitis, Lupus-ähnliche Reaktionen, Nervenentzündungen","Geschmacks- und Geruchsstörungen"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem","Schilddrüsenunterfunktion und Kropfwachstum bei zu hoher Dosis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung in der niedrigsten wirksamen Dosis und ohne zusätzliches Levothyroxin. Im ersten Schwangerschaftsdrittel kann Carbimazol Fehlbildungen verursachen (z. B. Hautdefekte am Kopf, Fehlbildungen von Gesicht, Speiseröhre oder Bauchwand); in dieser Zeit wird meist ein anderes Thyreostatikum bevorzugt.","stillzeit":"Geht in die Muttermilch über. Stillen ist nur nach ärztlicher Abwägung bei niedriger Dosis und mit Kontrolle der Schilddrüsenwerte des Kindes möglich.","hinweise":["Bei Fieber, Halsschmerzen, Mundgeschwüren oder grippeähnlichen Beschwerden sofort ärztliche Hilfe suchen und das Blutbild bestimmen lassen.","Regelmässige Kontrollen von Schilddrüsenwerten, Blutbild und Leberwerten.","Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","Die Wirkung setzt erst nach einigen Wochen ein; nicht eigenmächtig absetzen."],"darreichung":["Tabletten"]},"carboplatin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen, sodass sie sich nicht mehr teilen können. Carboplatin wird in der Zelle in reaktive Platinkomplexe umgewandelt, die DNA-Stränge vernetzen und so DNA-Synthese und Zellteilung blockieren. Wirkprinzip und Wirkspektrum ähneln Cisplatin; Carboplatin ist weniger nieren-, nerven- und gehörschädigend, hemmt aber das Knochenmark stärker. Die Dosis wird meist anhand der Nierenfunktion berechnet.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Neutropenie und Leukopenie (Mangel an weissen Blutkörperchen)","Anämie (Blutarmut)","Übelkeit und Erbrechen","Bauchschmerzen","Elektrolytverluste (Natrium, Kalium, Calcium, Magnesium)","Anstieg von Leberwerten (alkalische Phosphatase)"],"haeufig":["Infektionen","Blutungen","Allergische Reaktionen","Periphere Neuropathie (Kribbeln, Taubheit)","Hörstörungen, Tinnitus (Ohrgeräusche)","Durchfall, Verstopfung","Haarausfall","Geschmacksstörungen, Schwäche"],"gelegentlich":["Akute Leukämie oder andere Zweitkrebserkrankungen als Spätfolge"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Hämolytisch-urämisches Syndrom (Blutzerfall mit Nierenversagen)","Herzinsuffizienz, Schlaganfall, Embolien","Sehstörungen bis vorübergehende Erblindung","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Tumorlysesyndrom"]},"schwangerschaft":"Kontraindiziert, da Fruchtschäden möglich sind. Frauen und Männer sollen während und noch mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Vor jedem Zyklus wird das Blutbild kontrolliert; Fieber über 38 °C oder Blutungszeichen sofort melden.","Keine Lebendimpfungen während und einige Monate nach der Therapie.","Spermien- bzw. Eizellkonservierung vor Therapiebeginn besprechen (mögliche Unfruchtbarkeit)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"carglumsaeure":{"wirkmechanismus":"Ermöglicht dem Körper, giftiges Ammoniak wieder in Harnstoff umzuwandeln und über den Urin auszuscheiden. Carglumsäure ist ein Strukturanalogon von N-Acetylglutamat, dem natürlichen Aktivator der Carbamoylphosphat-Synthetase 1, des ersten Enzyms des Harnstoffzyklus in der Leber. Fehlt N-Acetylglutamat – angeboren beim NAGS-Mangel oder durch Hemmung der Synthase bei Organoazidurien –, aktiviert Carglumsäure das Enzym direkt und senkt so den Ammoniakspiegel.","nebenwirkungen":{"haeufig":["Vermehrtes Schwitzen (Hyperhidrose)"],"gelegentlich":["Bradykardie (langsamer Puls)","Durchfall, Erbrechen","Fieber","Erhöhte Leberwerte (Transaminasen)"],"unbekannt":["Hautausschlag"]},"schwangerschaft":"Nur begrenzte Erfahrungen; im Tierversuch geringe Entwicklungstoxizität. Anwendung nur nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Kontraindiziert: Carglumsäure geht bei Ratten in die Milch über und schadete den Jungtieren. Während der Behandlung nicht stillen.","hinweise":["Tabletten nicht ganz schlucken und nicht zerkauen: in etwas Wasser zerfallen lassen und sofort trinken; Gabe auch über eine Magensonde möglich.","Vor den Mahlzeiten einnehmen.","Ungeöffnet im Kühlschrank lagern; nach dem ersten Öffnen nicht mehr kühlen, unter 30 °C aufbewahren und innerhalb eines Monats verbrauchen.","Bei Erbrechen, Schläfrigkeit oder Verwirrtheit sofort ärztliche Hilfe holen – mögliche Zeichen eines Ammoniakanstiegs."],"darreichung":["Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"carvedilol":{"wirkmechanismus":"Senkt Blutdruck und Puls und entlastet das Herz, indem es die Wirkung der Stresshormone dämpft und gleichzeitig die Blutgefässe weitet. Carvedilol blockiert nicht selektiv die Beta-1- und Beta-2-Adrenozeptoren und senkt so Herzfrequenz, Kontraktionskraft und Reninfreisetzung. Die zusätzliche Blockade der Alpha-1-Rezeptoren in den Gefässwänden erweitert die Gefässe und senkt den peripheren Widerstand. Carvedilol wird in der Leber vor allem über CYP2D6 und CYP2C9 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Müdigkeit und Schwäche (Asthenie)","Hypotonie (tiefer Blutdruck)","Verschlechterung einer Herzschwäche, vor allem zu Beginn und bei Dosiserhöhung"],"haeufig":["Bradykardie (langsamer Puls), Ödeme (Wassereinlagerungen)","Blutdruckabfall beim Aufstehen, kalte Hände und Füsse","Atemnot; Asthmaanfälle bei entsprechender Veranlagung","Bronchitis, Lungenentzündung, Harnwegsinfekte","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Depression, depressive Verstimmung","Sehstörungen, verminderter Tränenfluss (trockene Augen)","Schlechtere Blutzuckereinstellung bei Diabetes, Gewichtszunahme; Verschlechterung der Nierenfunktion bei Gefässerkrankung oder Nierenschwäche"],"gelegentlich":["AV-Block, Angina pectoris","Synkope (Ohnmacht), Kribbeln (Parästhesien)","Schlafstörungen","Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht, psoriasisartige Veränderungen), Haarausfall","Erektionsstörungen","Verstopfung"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)","Verstopfte Nase","Mundtrockenheit"],"sehrSelten":["Leukopenie (Mangel an weissen Blutkörperchen)","Allergische Reaktionen","Erhöhte Leberwerte","Harninkontinenz bei Frauen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)"],"unbekannt":["Halluzinationen","Vermehrtes Schwitzen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: Betablocker können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes hemmen. Neugeborene in den ersten Lebenstagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Stillen wird nicht empfohlen; Carvedilol und seine Abbauprodukte gehen (im Tierversuch) in die Muttermilch über.","hinweise":["Mit einer Mahlzeit einnehmen – bei Herzschwäche verringert das Schwindel und Blutdruckabfall beim Aufstehen.","Nicht abrupt absetzen (Gefahr von Angina-pectoris-Anfällen und Blutdruckanstieg); ein Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Zu Beginn und bei Dosiserhöhung Schwindel und Müdigkeit möglich; Vorsicht beim Autofahren, Alkohol verstärkt dies.","Bei Herzschwäche täglich wiegen: rasche Gewichtszunahme oder zunehmende Atemnot ärztlich melden."],"darreichung":["Tabletten"]},"caspofungin":{"wirkmechanismus":"Schädigt die Zellwand von Pilzen, sodass diese platzen oder nicht mehr wachsen können. Caspofungin hemmt nicht-kompetitiv das Enzym β-(1,3)-D-Glucan-Synthase, das einen wesentlichen Baustein der Pilzzellwand herstellt; menschliche Zellen besitzen dieses Enzym nicht. Gegen Candida wirkt es abtötend, gegen Aspergillus hemmt es das Wachstum der Pilzfäden. Caspofungin wird nicht über Cytochrom-P450 abgebaut und hat daher wenige Wechselwirkungen.","nebenwirkungen":{"haeufig":["Abfall von Hämoglobin, Hämatokrit und weissen Blutkörperchen","Hypokaliämie (Kaliummangel)","Kopfschmerzen","Venenentzündung an der Infusionsstelle (Phlebitis)","Atemnot","Übelkeit, Durchfall, Erbrechen","Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase, Bilirubin)","Ausschlag, Juckreiz, Hautrötung, Schwitzen, Gelenkschmerzen, Fieber, Schüttelfrost"],"gelegentlich":["Anämie, Thrombozytopenie, Gerinnungsstörungen","Flüssigkeitsüberladung, Hypomagnesiämie, Hyperglykämie, Appetitlosigkeit","Angst, Schlaflosigkeit, Verwirrtheit","Schwindel, Geschmacksstörungen, Kribbeln, Zittern","Herzrhythmusstörungen (z. B. Vorhofflimmern), Herzklopfen, Herzinsuffizienz","Blutdruckabfall oder -anstieg, Hitzewallungen","Bronchospasmus, Husten","Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Cholestase, Gelbsucht, Leberfunktionsstörung","Nesselsucht, Erythema multiforme","Muskelschmerzen, Nierenfunktionsstörung bis akutes Nierenversagen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Akutes Atemnotsyndrom (ARDS)","Hyperkalzämie","Periphere Ödeme"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird im Spital einmal täglich als Infusion über etwa 1 Stunde verabreicht.","Ausschlag, Schwellungen, Juckreiz, Wärmegefühl oder Atemnot während der Infusion sofort melden.","Leberwerte und Elektrolyte werden während der Behandlung kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"cefazolin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefazolin hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Als Cephalosporin der 1. Generation wirkt es besonders gut gegen grampositive Keime wie Methicillin-empfindliche Staphylokokken und Streptokokken, gegen gramnegative Erreger nur begrenzt. Gegen MRSA und Enterokokken ist es unwirksam.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Appetitlosigkeit, Durchfall, Bauchschmerzen","Schmerzen an der Einstichstelle, Venenentzündung (Phlebitis) bei Infusion"],"gelegentlich":["Hautausschlag, Nesselsucht, Juckreiz","Pilzinfektion von Mund oder Scheide (Candidose)"],"selten":["Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie, Eosinophilie)","Vorübergehender Anstieg der Leberwerte","Nierenfunktionsstörung, interstitielle Nephritis (Nierenentzündung)","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Hämolytische Anämie (Blutzerfall)"],"unbekannt":["Krampfanfälle bei hohen Dosen und eingeschränkter Nierenfunktion","Gerinnungsstörungen mit Blutungen (Hypoprothrombinämie)","Positiver Coombs-Test"]},"schwangerschaft":"Kann angewendet werden, wenn nötig; breite Erfahrung, z. B. als Infektionsvorbeugung beim Kaiserschnitt, ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung ist möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird im Spital oder in der Praxis als Injektion oder Infusion gegeben.","Allergien gegen Penicilline oder Cephalosporine vor der Gabe unbedingt melden.","Bei längerer Behandlung Blutbild und Nierenwerte kontrollieren."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cefpodoxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefpodoxim-Proxetil ist eine Vorstufe (Prodrug), die beim Durchtritt durch die Darmwand zum wirksamen Cefpodoxim gespalten wird. Dieses hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Pneumokokken, Haemophilus influenzae, Moraxella und viele E.-coli-Stämme; gegen Staphylokokken nur mässig, gegen Pseudomonas, Enterokokken und MRSA nicht.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Blähungen"],"gelegentlich":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Hautausschlag, Nesselsucht, Juckreiz","Müdigkeit, Schwäche"],"selten":["Blutbildveränderungen (Abfall des Hämoglobins, Thrombozytose, Thrombozytopenie, Leukopenie, Eosinophilie)","Anstieg von Leber- und Nierenwerten"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Angioödem, Bronchospasmus","Pseudomembranöse Kolitis (schwere Darmentzündung)","Leberschädigung (meist mit Gallestau)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Pilzinfektionen (Mund, Scheide)","Ohrensausen (Tinnitus)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung anwenden oder abstillen.","hinweise":["Tabletten mit einer Mahlzeit einnehmen – so wird Cefpodoxim besser aufgenommen.","Antazida und andere säurebindende Mittel mit 2–3 Stunden Abstand einnehmen.","Die verordnete Behandlungsdauer einhalten; bei Hautausschlag oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen"]},"ceftazidim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftazidim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt vor allem gegen gramnegative Bakterien einschliesslich Pseudomonas aeruginosa, gegen grampositive Keime wie Staphylokokken dagegen nur schwach. Bakterien mit Beta-Laktamasen vom ESBL- oder AmpC-Typ sowie Carbapenemase-Bildner sind meist resistent. Ceftazidim wird fast unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Eosinophilie, Thrombozytose (Vermehrung der Blutplättchen)","Venenentzündung (Phlebitis) bei Infusion, Schmerzen und Entzündung an der Einstichstelle","Durchfall","Vorübergehender Anstieg der Leberwerte","Hautausschlag (fleckig oder mit Quaddeln)","Positiver Coombs-Test"],"gelegentlich":["Pilzinfektionen (Candidose)","Leukopenie, Neutropenie, Thrombozytopenie","Kopfschmerzen, Schwindel","Antibiotika-assoziierte Kolitis, Bauchschmerzen, Übelkeit, Erbrechen","Juckreiz, Fieber","Vorübergehender Anstieg der Nierenwerte"],"sehrSelten":["Interstitielle Nephritis (Nierenentzündung), akutes Nierenversagen"],"unbekannt":["Agranulozytose, hämolytische Anämie, Lymphozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock)","Neurologische Störungen bei eingeschränkter Nierenfunktion (Zittern, Muskelzuckungen, Krampfanfälle, Enzephalopathie, Koma)","Kribbeln (Parästhesien), Geschmacksstörung","Gelbsucht","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Angioödem"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Wird im Spital als Injektion oder Infusion gegeben.","Bei eingeschränkter Nierenfunktion wird die Dosis angepasst; Verwirrtheit oder Muskelzuckungen sofort melden.","Allergien gegen Penicilline oder Cephalosporine vor der Behandlung angeben."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"ceftriaxon":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftriaxon hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt gegen viele grampositive und gramnegative Bakterien wie Pneumokokken, Streptokokken, Meningokokken, Gonokokken, Haemophilus und zahlreiche Darmbakterien und dringt gut in die Hirnhäute ein. Dank seiner langen Halbwertszeit (etwa 8 Stunden) genügt meist eine Gabe pro Tag; ausgeschieden wird es etwa je zur Hälfte über Niere und Galle. Gegen Pseudomonas, Enterokokken, MRSA und ESBL-Bildner ist es nicht zuverlässig wirksam.","nebenwirkungen":{"haeufig":["Eosinophilie, Leukopenie, Thrombozytopenie","Durchfall, weicher Stuhl","Anstieg der Leberwerte","Hautausschlag"],"gelegentlich":["Pilzinfektion im Genitalbereich","Granulozytopenie, Anämie, Gerinnungsstörung","Kopfschmerzen, Schwindel","Übelkeit, Erbrechen","Juckreiz","Venenentzündung, Schmerzen an der Einstichstelle, Fieber","Anstieg des Kreatinins (Nierenwert)"],"selten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Bronchospasmus (Verkrampfung der Atemwege)","Nesselsucht (Urtikaria)","Blut oder Zucker im Urin, Ödeme, Schüttelfrost"],"unbekannt":["Hämolytische Anämie (Blutzerfall, auch schwer), Agranulozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock), Kounis-Syndrom","Ceftriaxon-Calcium-Ablagerungen in Gallenblase und Nieren, Gallenkolik, Pankreatitis","Krampfanfälle, Enzephalopathie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Kernikterus (Bilirubin-Hirnschädigung) bei Neugeborenen","Jarisch-Herxheimer-Reaktion bei Borreliose oder Syphilis"]},"schwangerschaft":"Passiert die Plazenta; nach ärztlicher Abwägung möglich, besonders im 1. Drittel nur bei klarer Notwendigkeit. Bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird als Injektion oder Infusion gegeben; die Zubereitung mit Lidocain darf nur in den Muskel gespritzt werden.","Starke Schmerzen im rechten Oberbauch, Blässe, dunkler Urin oder Atemnot während der Behandlung sofort melden.","Bei längerer Behandlung wird das Blutbild kontrolliert; ausreichend trinken."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung","Pulver mit Lidocain-haltigem Lösungsmittel zur Injektion in den Muskel"]},"cefuroxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefuroxim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Methicillin-empfindliche Staphylokokken, Haemophilus influenzae, Moraxella sowie einen Teil der Darmbakterien wie E. coli. Die Tablettenform Cefuroxim-Axetil ist eine Vorstufe, die in der Darmwand zu Cefuroxim gespalten wird.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit, Bauchschmerzen","Pilzinfektionen (z. B. Mund oder Scheide)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Vorübergehender Anstieg der Leberwerte","Bei Infusion: Schmerzen oder Venenentzündung an der Einstichstelle"],"gelegentlich":["Erbrechen","Hautausschlag","Thrombozytopenie, Leukopenie","Positiver Coombs-Test"],"unbekannt":["Clostridioides-difficile-Infektion, pseudomembranöse Kolitis (schwere Darmentzündung)","Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Arzneimittelfieber, Serumkrankheit","Jarisch-Herxheimer-Reaktion","Gelbsucht (meist durch Gallestau), Leberentzündung","Nesselsucht, Juckreiz, Angioödem","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Interstitielle Nephritis, Anstieg der Nierenwerte (Infusion)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Tabletten nach einer Mahlzeit einnehmen – so werden sie besser aufgenommen; nicht zerkauen oder zerdrücken (sehr bitterer Geschmack).","Die verordnete Behandlungsdauer einhalten.","Kann Schwindel verursachen – Vorsicht beim Autofahren und Bedienen von Maschinen.","Bei Hautausschlag, Atemnot oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"celecoxib":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen und schont dabei die Magenschleimhaut etwas mehr als herkömmliche NSAR. Celecoxib hemmt selektiv die Cyclooxygenase-2 (COX-2), die im entzündeten Gewebe Prostaglandine bildet; die für Magenschutz und Blutplättchen wichtige COX-1 wird in therapeutischer Dosis kaum gehemmt. Deshalb hemmt Celecoxib die Blutplättchen nicht und ersetzt keine Acetylsalicylsäure zum Herzschutz. Abgebaut wird es hauptsächlich über CYP2C9.","nebenwirkungen":{"haeufig":["Bluthochdruck","Dyspepsie (Verdauungsbeschwerden), Bauchschmerzen, Durchfall, Blähungen","Schwindel, Schlaflosigkeit","Hautausschlag, Juckreiz","Periphere Ödeme (Wassereinlagerungen)","Infekte der oberen Atemwege, Nasennebenhöhlenentzündung, Harnwegsinfekte"],"gelegentlich":["Anämie (Blutarmut)","Hyperkaliämie (erhöhtes Kalium)","Sehstörungen, Ohrensausen (Tinnitus)","Herzinsuffizienz, Herzklopfen","Erhöhte Leber- und Nierenwerte","Nesselsucht"],"selten":["Magen-Darm-Geschwüre, -Blutungen und -Durchbrüche","Pankreatitis (Bauchspeicheldrüsenentzündung), Hepatitis","Angioödem (Schwellung von Haut und Schleimhaut)","Blutbildveränderungen","Verwirrtheit","Akutes Nierenversagen"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Leberversagen","Hirnblutung"],"unbekannt":["Herzinfarkt und Schlaganfall (Risiko steigt mit Dosis und Behandlungsdauer)","Vorübergehend verminderte Fruchtbarkeit bei Frauen"]},"schwangerschaft":"Kontraindiziert. Frauen, die schwanger werden können, sollen während der Behandlung wirksam verhüten.","stillzeit":"Kontraindiziert; Celecoxib geht in geringen Mengen in die Muttermilch über.","hinweise":["Mit oder ohne Essen einnehmen; so niedrig dosiert und so kurz wie möglich.","Ersetzt keine Acetylsalicylsäure zum Schutz von Herz und Gefässen.","Blutdruck regelmässig kontrollieren.","Kann Schwindel verursachen – Vorsicht beim Autofahren."],"darreichung":["Kapseln"]},"celiprolol":{"wirkmechanismus":"Senkt Blutdruck und Puls, indem es die Wirkung von Stresshormonen am Herzen abschwächt. Celiprolol blockiert bevorzugt die Beta-1-Rezeptoren des Herzens und regt gleichzeitig in geringem Mass Beta-2-Rezeptoren an (partielle agonistische Aktivität), was die Gefässe leicht erweitert. Es wird kaum verstoffwechselt und weitgehend unverändert ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Müdigkeit"],"unbekannt":["Übelkeit, Magen-Darm-Beschwerden","Schlafstörungen, depressive Verstimmung","Bradykardie (langsamer Puls), Blutdruckabfall","Bronchospasmus (Verkrampfung der Atemwege)","Kalte Hände und Füsse","Hautausschlag, Verschlechterung einer Psoriasis","Verdeckte Unterzuckerungszeichen bei Diabetes"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Betablocker können das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls und Unterzuckerung verursachen.","stillzeit":"Nicht empfohlen bzw. nur nach strenger ärztlicher Abwägung; Säugling auf langsamen Puls und Unterzuckerung beobachten.","hinweise":["Morgens nüchtern, mindestens 30 Minuten vor oder 2 Stunden nach einer Mahlzeit mit Wasser einnehmen; nicht mit Grapefruit- oder Orangensaft.","Nicht abrupt absetzen, sondern ausschleichen.","Kann besonders zu Beginn und zusammen mit Alkohol die Fahrtüchtigkeit beeinträchtigen.","Vor Operationen die Behandlung angeben."],"darreichung":["Filmtabletten"]},"cerliponase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das in Nervenzellen Eiweissabbauprodukte zerlegt, und verlangsamt so den Verlust der Geh- und Sprechfähigkeit. Cerliponase alfa ist die gentechnisch hergestellte inaktive Vorstufe (Proenzym) der menschlichen Tripeptidylpeptidase 1. Sie wird über ein unter der Kopfhaut implantiertes Reservoir mit Katheter in die Hirnkammern gegeben, über Mannose-6-Phosphat-Rezeptoren von Nervenzellen aufgenommen und in den Lysosomen aktiviert. Dort spaltet sie Tripeptide von Eiweissen ab und vermindert die Ablagerung von Speichermaterial.","nebenwirkungen":{"sehrHaeufig":["Fieber","Erbrechen","Überempfindlichkeitsreaktionen","Krampfanfälle","Kopfschmerzen","Reizbarkeit","EKG-Veränderungen","Veränderungen im Hirnwasser (erhöhte Zellzahl, verändertes Eiweiss)"],"haeufig":["Infektionen des Zugangssystems, Hirnhautentzündung","Probleme mit dem Zugangssystem (Leck, Verstopfung, Nadelprobleme)","Bradykardie (langsamer Puls)"]},"schwangerschaft":"Keine Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Keine Daten. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen über mehrere Stunden in einem spezialisierten Zentrum über das implantierte Reservoir gegeben; das Zugangssystem wird regelmässig geprüft und bei Bedarf ersetzt.","Fieber, Kopfschmerzen, Nackensteife, Rötung oder Flüssigkeitsaustritt am Reservoir sofort melden.","Herz und Kreislauf werden während jeder Gabe überwacht."],"darreichung":["Infusionslösung zur Gabe in die Hirnkammern (intraventrikulär)"]},"cetirizin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin, das bei allergischen Reaktionen Niesen, Juckreiz, Quaddeln und tränende Augen auslöst. Cetirizin ist ein selektiver Antagonist an peripheren Histamin-H1-Rezeptoren und der wirksame Hauptmetabolit von Hydroxyzin. Es gelangt nur in geringem Mass ins Gehirn und wirkt kaum anticholinerg; deshalb macht es weniger müde als ältere Antihistaminika. Es wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit (Somnolenz)","Kopfschmerzen","Schwindel","Mundtrockenheit","Übelkeit","Rachenentzündung (Pharyngitis)"],"gelegentlich":["Unruhe (Agitiertheit)","Kribbeln (Parästhesien)","Bauchschmerzen, Durchfall","Juckreiz, Hautausschlag","Schwäche (Asthenie), Unwohlsein"],"selten":["Überempfindlichkeitsreaktionen","Aggressivität, Verwirrtheit, Depression, Halluzinationen, Schlaflosigkeit","Krampfanfälle","Herzrasen (Tachykardie)","Abweichende Leberwerte","Nesselsucht, Ödeme (Wassereinlagerungen), Gewichtszunahme"],"sehrSelten":["Anaphylaktischer Schock","Thrombozytopenie (Mangel an Blutplättchen)","Ohnmacht (Synkope), Zittern, Geschmacksstörungen, Tics","Sehstörungen (Akkommodationsstörungen, verschwommenes Sehen)","Angioödem (Schwellung von Haut und Schleimhäuten), fixes Arzneimittelexanthem","Schmerzhaftes Wasserlassen, Einnässen"],"unbekannt":["Harnverhalt","Juckreiz nach dem Absetzen","Suizidgedanken, Albträume, Gedächtnisstörungen","Gelenk- und Muskelschmerzen","Akute generalisierte exanthematische Pustulose (AGEP, schwere Hautreaktion)","Hepatitis (Leberentzündung)","Appetitsteigerung"]},"schwangerschaft":"Umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko. Trotzdem nur nach ärztlicher Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Abwägung anwenden und beim Säugling auf Schläfrigkeit achten.","hinweise":["Kann trotz geringer Sedierung die Reaktionsfähigkeit beeinträchtigen – die eigene Reaktion vor dem Autofahren prüfen; Alkohol meiden.","Vor Allergie-Hauttests 3 Tage absetzen, sonst können die Resultate falsch negativ ausfallen.","Bei eingeschränkter Nierenfunktion ist eine tiefere Dosis nötig."],"darreichung":["Filmtabletten","Tropfen zum Einnehmen"]},"chlorhexidin":{"wirkmechanismus":"Tötet Bakterien ab und hemmt Pilze auf Haut und Schleimhaut. Das positiv geladene Chlorhexidin bindet an die negativ geladene Zellwand der Mikroorganismen, macht die Zellmembran durchlässig und führt in höherer Konzentration zum Absterben der Keime. Es wirkt besonders gut gegen grampositive, etwas schwächer gegen gramnegative Bakterien und Hefepilze, gegen Sporen kaum. Weil es an Zähnen und Schleimhaut haftet und langsam wieder freigesetzt wird, hält die Wirkung im Mund mehrere Stunden an (Depotwirkung).","nebenwirkungen":{"haeufig":["Bräunliche Verfärbungen von Zähnen, Füllungen, Prothesen und Zunge (rückbildungsfähig, durch professionelle Zahnreinigung entfernbar)","Belegte Zunge","Vorübergehende Geschmacksstörungen","Brennen oder Taubheitsgefühl der Zunge"],"selten":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Rötung, Juckreiz)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion bis zum Schock)"],"unbekannt":["Reizung oder Abschuppung der Mundschleimhaut","Rückbildungsfähige Schwellung der Ohrspeicheldrüse","Vermehrte Zahnsteinbildung","Hautreizung oder Kontaktekzem bei Anwendung auf der Haut","Hautverätzungen bei Frühgeborenen"]},"schwangerschaft":"Bei Anwendung im Mund oder auf der Haut wird kaum Wirkstoff ins Blut aufgenommen; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich; nicht im Bereich der Brust anwenden, damit der Säugling den Wirkstoff nicht aufnimmt.","hinweise":["Mundspülung nach dem Spülen ausspucken und nicht schlucken; nicht unmittelbar nach dem Zähneputzen anwenden.","Kaffee, Tee, Rotwein und Rauchen verstärken die Verfärbungen der Zähne.","Ohne zahnärztlichen Rat die Mundspülung nicht länger als etwa 2 Wochen anwenden.","Bei Kontakt mit den Augen sofort gründlich mit Wasser spülen."],"darreichung":["Mundspüllösung","Lösung und Spray zur Haut- und Wunddesinfektion","Crème und Spray (Kombination mit Dexpanthenol)"]},"chlortalidon":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere und senkt so den Blutdruck. Chlortalidon hemmt wie die Thiazide den Natrium-Chlorid-Cotransporter im frühdistalen Tubulus; dadurch werden mehr Natrium, Chlorid und Wasser, aber auch Kalium und Magnesium ausgeschieden, Calcium dagegen zurückgehalten. Die Dauerwirkung auf den Blutdruck beruht zusätzlich auf einer Abnahme des Gefässwiderstands. Wegen der sehr langen Halbwertszeit von rund 50 Stunden (Bindung an die roten Blutkörperchen) hält die Wirkung 48–72 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Hyperurikämie (erhöhte Harnsäure)","Erhöhte Blutfette, vor allem bei höheren Dosen"],"haeufig":["Hyponatriämie (Natriummangel), Hypomagnesiämie (Magnesiummangel)","Hyperglykämie (erhöhter Blutzucker)","Nesselsucht und andere Hautausschläge","Orthostatische Hypotonie (Schwindel beim Aufstehen), verstärkt durch Alkohol oder Beruhigungsmittel","Appetitlosigkeit, leichte Magen-Darm-Beschwerden","Erektionsstörungen","Schwindel"],"selten":["Hyperkalzämie (erhöhtes Calcium)","Verschlechterung eines Diabetes, Zucker im Urin, Gichtanfälle","Photosensibilität (Lichtempfindlichkeit der Haut)","Herzrhythmusstörungen","Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Durchfall","Gallenstau in der Leber (intrahepatische Cholestase), Gelbsucht","Kopfschmerzen, Kribbeln (Parästhesien), Sehstörungen","Thrombozytopenie, Leukopenie, Agranulozytose, Eosinophilie"],"sehrSelten":["Hypochlorämische Alkalose","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenödem als Überempfindlichkeitsreaktion","Allergische interstitielle Nephritis (Nierenentzündung)","Vaskulitis (Gefässentzündung)"],"unbekannt":["Akute Kurzsichtigkeit, Aderhauterguss, akutes Engwinkelglaukom"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; nicht bei schwangerschaftsbedingten Ödemen, Bluthochdruck oder Präeklampsie, da es die Durchblutung der Plazenta vermindern und beim Neugeborenen Gelbsucht, Elektrolytstörungen und Blutplättchenmangel verursachen kann.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; in der Stillzeit nicht anwenden.","hinweise":["Am Morgen einnehmen; die Wirkung hält 2–3 Tage an, deshalb kann sie nach dem Absetzen noch nachwirken.","Kalium, Natrium, Nierenwerte, Harnsäure und Blutzucker regelmässig kontrollieren lassen; bei Erbrechen, Durchfall oder starkem Schwitzen ärztlichen Rat einholen.","Haut vor starker Sonne schützen (Lichtempfindlichkeit).","Bei plötzlicher Sehverschlechterung oder Augenschmerzen sofort ärztliche Hilfe suchen."],"darreichung":["Tabletten"]},"choriongonadotropin":{"wirkmechanismus":"Löst den Eisprung aus, nachdem die Eibläschen (Follikel) herangereift sind. Choriongonadotropin wirkt wie das körpereigene luteinisierende Hormon (LH) am LH/hCG-Rezeptor: Es bewirkt die abschliessende Reifung der Eizelle, den Eisprung und die Bildung des Gelbkörpers. Beim Mann regt es die Leydig-Zellen im Hoden zur Bildung von Testosteron an. Ovitrelle enthält gentechnisch hergestelltes hCG (Choriogonadotropin alfa), Pregnyl und Brevactid aus dem Urin schwangerer Frauen gewonnenes hCG.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Schwellung)","Übelkeit, Erbrechen, Bauchschmerzen","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Durchfall","Depression, Reizbarkeit, Unruhe","Brustschmerzen","Schweres ovarielles Überstimulationssyndrom"],"sehrSelten":["Thromboembolie (meist zusammen mit schwerem OHSS)","Überempfindlichkeitsreaktionen bis Anaphylaxie, Hautausschlag"],"unbekannt":["Männer: Wassereinlagerungen, Brustvergrösserung (Gynäkomastie), Akne"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft. Nach Kinderwunschbehandlungen sind Fehlgeburten, Eileiter- und Mehrlingsschwangerschaften häufiger.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Den von der Ärztin oder vom Arzt festgelegten Injektionszeitpunkt genau einhalten; Eizellentnahme oder Geschlechtsverkehr werden darauf abgestimmt.","Schwangerschaftstests können bis etwa 10 Tage nach der Injektion falsch positiv ausfallen.","Bei starken Bauchschmerzen, Blähbauch, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen (Überstimulation)."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"ciclopirox":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen und tötet sie ab. Ciclopirox bindet (chelatiert) dreiwertige Metallionen wie Eisen und Aluminium und blockiert dadurch eisenabhängige Enzyme, die der Pilz für seinen Stoffwechsel und die Entgiftung von Sauerstoffradikalen braucht. Es wirkt breit gegen Dermatophyten, Hefen und Schimmelpilze, zusätzlich gegen einige Bakterien, und dämpft Entzündungen leicht. Aus dem Nagellack dringt der Wirkstoff in die Nagelplatte ein.","nebenwirkungen":{"gelegentlich":["Brennen und Juckreiz an der Anwendungsstelle (Creme, Lösung)"],"sehrSelten":["Rötung und Schuppung der Haut rund um den behandelten Nagel (Nagellack)","Allergische Kontaktdermatitis (juckender Ausschlag an der Auftragsstelle)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Es gibt kaum Erfahrungen, die Aufnahme in den Körper ist bei äusserlicher Anwendung aber gering.","stillzeit":"Nach ärztlicher Abwägung möglich, da kaum Wirkstoff in den Körper gelangt; nicht im Brustbereich auftragen.","hinweise":["Nagelpilz braucht Geduld: Die Behandlung dauert meist mehrere Monate (Fingernägel etwa 6, Zehennägel 9–12 Monate), bis der Nagel gesund nachgewachsen ist.","Während der Behandlung mit dem Nagellack keinen kosmetischen Nagellack und keine künstlichen Nägel verwenden.","Nicht in die Augen oder auf Schleimhäute bringen.","Keine Besserung nach etwa 6 Monaten: ärztlich kontrollieren lassen."],"darreichung":["Nagellack (wirkstoffhaltig)","Creme","Lösung zur Anwendung auf der Haut"]},"ciclosporin":{"wirkmechanismus":"Hemmt die Aktivierung bestimmter Abwehrzellen (T-Lymphozyten), die transplantierte Organe angreifen oder Autoimmunentzündungen antreiben. Ciclosporin bindet in der Zelle an Cyclophilin; dieser Komplex hemmt das Enzym Calcineurin. Dadurch wird die Bildung von Interleukin-2 und anderen Botenstoffen unterdrückt, und T-Zellen vermehren sich nicht. Als Augentropfen wirkt es örtlich entzündungshemmend auf Hornhaut und Bindehaut.","nebenwirkungen":{"sehrHaeufig":["Nierenfunktionsstörung (Anstieg des Kreatinins)","Bluthochdruck","Zittern (Tremor), Kopfschmerzen","Erhöhte Blutfette"],"haeufig":["Erhöhtes Kalium, Magnesiummangel, erhöhte Harnsäure, erhöhter Blutzucker","Appetitlosigkeit, Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Zahnfleischwucherung (Gingivahyperplasie)","Leberfunktionsstörungen","Vermehrte Körperbehaarung (Hypertrichose), Akne","Parästhesien (Kribbeln, Brennen), Krampfanfälle","Muskelkrämpfe, Muskelschmerzen","Leukopenie, Fieber, Müdigkeit"],"gelegentlich":["Anämie, Thrombozytopenie","Hirnstörungen (Enzephalopathie, PRES) mit Krampfanfällen, Verwirrtheit, Sehstörungen","Ödeme, Gewichtszunahme","Allergischer Hautausschlag"],"selten":["Thrombotische Mikroangiopathie, hämolytisch-urämisches Syndrom","Periphere Neuropathie (Nervenschädigung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Muskelschwäche, Myopathie","Menstruationsstörungen, Brustvergrösserung beim Mann"],"sehrSelten":["Papillenödem (Sehnervschwellung) mit Sehstörungen"],"unbekannt":["Schwere Leberschäden bis Leberversagen","Lymphome und Hautkrebs (bei Langzeitimmunsuppression)","Opportunistische Infektionen, auch PML und BK-Virus-Nephropathie","Augentropfen: Augenschmerzen, Augenreizung, Brennen nach dem Eintropfen (sehr häufig)"]},"schwangerschaft":"Nur bei zwingender Indikation (z. B. nach Transplantation) nach ärztlicher Abwägung; kein Hinweis auf Fehlbildungen, aber mehr Frühgeburten und tiefes Geburtsgewicht. Augentropfen in der Schwangerschaft nicht empfohlen.","stillzeit":"Ciclosporin geht in die Muttermilch über; unter systemischer Therapie wird vom Stillen abgeraten.","hinweise":["Immer gleich und regelmässig einnehmen; keinen Grapefruitsaft und kein Johanniskraut.","Ciclosporin-Spiegel, Nierenwerte, Blutdruck, Kalium und Leberwerte werden regelmässig kontrolliert.","Nicht ohne Rücksprache zwischen verschiedenen Ciclosporin-Präparaten wechseln (unterschiedliche Aufnahme).","Gute Mundhygiene gegen Zahnfleischwucherung; konsequenter Sonnenschutz."],"darreichung":["Weichkapseln","Lösung zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung","Augentropfen (Emulsion)"]},"cimicifuga":{"wirkmechanismus":"Lindert typische Wechseljahresbeschwerden wie Hitzewallungen und Schweissausbrüche. Der Wirkmechanismus des Extrakts aus dem Wurzelstock der Traubensilberkerze ist nicht vollständig geklärt. Nach heutigem Wissen wirkt er nicht wie ein klassisches Östrogen auf Brust und Gebärmutterschleimhaut, sondern beeinflusst vermutlich zentrale Botenstoffsysteme (u. a. Serotonin- und Opioidrezeptoren), die an der Temperaturregulation beteiligt sind.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Verdauungsbeschwerden, Durchfall)","Allergische Hautreaktionen (Nesselsucht, Juckreiz, Ausschlag)","Schwellungen im Gesicht, Wassereinlagerungen in Armen und Beinen (Ödeme)","Leberschädigung (Leberentzündung, Gelbsucht, veränderte Leberwerte), in Einzelfällen schwer"]},"schwangerschaft":"Nicht anwenden – keine ausreichenden Daten; das Mittel ist für Frauen in den Wechseljahren bestimmt.","stillzeit":"Nicht anwenden – keine ausreichenden Daten.","hinweise":["Die Wirkung setzt nach etwa 2 Wochen ein, die volle Wirkung oft erst nach mehreren Wochen.","Ohne ärztliche Rücksprache nicht länger als 6 Monate einnehmen.","Bei Anzeichen einer Leberschädigung (Gelbsucht, dunkler Urin, starke Müdigkeit, Oberbauchschmerzen) sofort absetzen und eine Ärztin oder einen Arzt aufsuchen.","Ersetzt keine ärztliche Abklärung von Blutungen nach der Menopause."],"darreichung":["Tabletten","Filmtabletten"]},"cinacalcet":{"wirkmechanismus":"Macht die Nebenschilddrüsen empfindlicher für Calcium, sodass sie weniger Parathormon ausschütten. Cinacalcet ist ein allosterischer Modulator des calciumsensitiven Rezeptors (CaSR) auf den Hauptzellen der Nebenschilddrüse: Schon niedrigere Calciumkonzentrationen hemmen dadurch die Parathormon-Freisetzung. In der Folge sinken Parathormon und Calcium im Blut, bei Dialysepatienten auch das Calcium-Phosphat-Produkt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen"],"haeufig":["Hypokalzämie (zu tiefes Calcium; z. B. Kribbeln, Muskelkrämpfe)","Krampfanfälle","Appetitlosigkeit","Schwindel, Kribbeln (Parästhesien), Kopfschmerzen","Blutdruckabfall (Hypotonie)","Durchfall, Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Muskelschmerzen, Muskelkrämpfe, Rückenschmerzen, Schwäche","Hautausschlag, Überempfindlichkeitsreaktionen, Hyperkaliämie (erhöhtes Kalium), tieferes Testosteron"],"unbekannt":["Verschlechterung einer Herzinsuffizienz","QT-Verlängerung und ventrikuläre Herzrhythmusstörungen infolge Hypokalzämie","Nesselsucht (Urtikaria)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Nicht bekannt, ob Cinacalcet in die Muttermilch übergeht; nach ärztlicher Abwägung entweder abstillen oder auf das Mittel verzichten.","hinweise":["Mit einer Mahlzeit oder kurz danach einnehmen – so wird Cinacalcet besser aufgenommen. Tabletten ganz schlucken, nicht teilen oder zerkauen.","Regelmässige Kontrollen von Calcium und Parathormon, besonders in den ersten Wochen und nach jeder Dosisänderung.","Kribbeln um den Mund oder in den Fingern, Muskelzuckungen, Krämpfe oder Krampfanfälle können Zeichen eines zu tiefen Calciums sein – sofort ärztlich melden.","Beginn oder Ende des Rauchens der Ärztin oder dem Arzt mitteilen."],"darreichung":["Filmtabletten"]},"cinchocain":{"wirkmechanismus":"Betäubt die Nervenenden in Haut und Schleimhaut des Afters und lindert so Schmerz und Juckreiz. Cinchocain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und verhindert dadurch die Weiterleitung von Schmerzreizen. Es gehört zu den stärksten und am längsten wirksamen Lokalanästhetika und wird heute nur noch oberflächlich angewendet.","nebenwirkungen":{"unbekannt":["Lokales Brennen","Allergische Kontaktdermatitis (juckender Ausschlag)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bei kortisonhaltigen Kombipräparaten besonders im ersten Schwangerschaftsdrittel zurückhaltend anwenden.","stillzeit":"Kurzfristige Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Nur äusserlich bzw. rektal anwenden und für Kinder unzugänglich aufbewahren – Cinchocain ist beim Verschlucken sehr giftig.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen.","Kann die Reissfestigkeit von Latexkondomen vermindern."],"darreichung":["Salbe","Zäpfchen"]},"cinnarizin-dimenhydrinat":{"wirkmechanismus":"Lindert Schwindel und begleitende Übelkeit über zwei sich ergänzende Wirkstoffe. Cinnarizin hemmt den Calciumeinstrom in die Sinneszellen des Gleichgewichtsorgans und verbessert die Durchblutung im Innenohr (peripherer Angriffspunkt). Dimenhydrinat ist ein sedierendes Antihistaminikum mit anticholinerger Wirkung, das die Gleichgewichtszentren im Hirnstamm dämpft (zentraler Angriffspunkt) und gegen Übelkeit wirkt.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Benommenheit","Kopfschmerzen","Mundtrockenheit","Bauchschmerzen"],"gelegentlich":["Kribbeln (Parästhesien), Zittern, Nervosität, Vergesslichkeit","Ohrensausen (Tinnitus)","Übelkeit, Dyspepsie (Verdauungsbeschwerden)","Schwitzen, Hautausschlag"],"unbekannt":["Krampfanfälle","Sehstörungen","Überempfindlichkeitsreaktionen, Lichtempfindlichkeit der Haut","Blutbildveränderungen (Leukopenie, Thrombozytopenie, aplastische Anämie)","Extrapyramidale Symptome (Bewegungsstörungen), vor allem bei älteren Menschen","Harnverhalt"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht anwenden.","stillzeit":"Dimenhydrinat geht in die Muttermilch über; nicht stillen.","hinweise":["Nach den Mahlzeiten unzerkaut mit etwas Flüssigkeit einnehmen.","In der Regel nicht länger als 4 Wochen ohne ärztliche Neubeurteilung anwenden.","Alkohol meiden; die Fahrtüchtigkeit ist häufig beeinträchtigt."],"darreichung":["Tabletten"]},"cipaglucosidase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Pompe fehlt, damit sich weniger Glykogen in den Muskelzellen ablagert. Cipaglucosidase alfa ist eine gentechnisch hergestellte saure Alpha-Glucosidase mit vielen Bis-Mannose-6-Phosphat-Zuckerketten, die über Mannose-6-Phosphat-Rezeptoren gut in die Muskelzellen aufgenommen wird. In den Lysosomen wird sie zur reifen Form aktiviert und spaltet Glykogen. Das kurz vorher eingenommene Miglustat bindet im Blut an das Enzym und stabilisiert es, sodass weniger aktives Enzym verloren geht.","nebenwirkungen":{"haeufig":["Infusionsbedingte Reaktionen und Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel, Zittern, Schläfrigkeit, Geschmacksstörung","Herzrasen, Hautrötung mit Hitzegefühl","Husten, Atemnot","Durchfall, Übelkeit, Bauchschmerzen, Blähungen, Verstopfung","Juckreiz, Ausschlag, Nesselsucht, vermehrtes Schwitzen","Muskelschmerzen, Muskelkrämpfe, Muskelschwäche","Müdigkeit, Schüttelfrost, Fieber, Schmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Die Kombination mit Miglustat wird in der Schwangerschaft nicht empfohlen (Miglustat im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während und bis 4 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; ein Risiko für den Säugling ist nicht auszuschliessen. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; die Miglustat-Kapseln werden etwa 1 Stunde vor Beginn der Infusion nüchtern eingenommen (2 Stunden vorher und 2 Stunden nachher nichts essen).","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden.","Zuverlässig verhüten; eine Schwangerschaft sofort der Ärztin oder dem Arzt mitteilen."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"ciprofloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es das Kopieren ihrer Erbsubstanz verhindert. Ciprofloxacin hemmt die bakteriellen Topoisomerasen II (DNA-Gyrase) und IV, die zum Entwinden und Trennen der DNA nötig sind; es entstehen tödliche DNA-Brüche. Es wirkt besonders gut gegen gramnegative Erreger einschliesslich Pseudomonas aeruginosa, schwächer gegen Pneumokokken und kaum gegen Anaerobier. Ciprofloxacin hemmt zudem das Leberenzym CYP1A2.","nebenwirkungen":{"haeufig":["Übelkeit, Durchfall","Bei Augentropfen: Augenbeschwerden, weissliche Ablagerungen auf der Hornhaut"],"gelegentlich":["Pilzinfektionen","Kopfschmerzen, Schwindel, Schlafstörungen, Geschmacksstörungen, Unruhe","Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Erhöhte Leberwerte und Bilirubin","Hautausschlag, Juckreiz, Nesselsucht","Gelenkschmerzen (bei Kindern häufig)","Eosinophilie, Appetitlosigkeit, Schwäche, Fieber"],"selten":["Antibiotika-assoziierte Kolitis (sehr selten pseudomembranös)","Blutbildveränderungen (Leukopenie, Anämie, Thrombozytopenie)","Verwirrtheit, Angst, Albträume, Depression bis Suizidgedanken, Halluzinationen","Krampfanfälle, Kribbeln und Missempfindungen, Zittern","Sehstörungen, Tinnitus, Hörverlust","Herzrasen, Blutdruckabfall, Ohnmacht","Unter- oder Überzuckerung","Lichtempfindlichkeit der Haut, Muskelschmerzen, Nierenversagen, Kristallurie"],"sehrSelten":["Sehnenentzündung und Sehnenriss (vor allem Achillessehne), Muskelschwäche, Verschlechterung einer Myasthenia gravis","Agranulozytose, hämolytische Anämie, Panzytopenie","Anaphylaktischer Schock","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Lebernekrose bis Leberversagen, Pankreatitis","Psychotische Reaktionen, Gangstörungen, erhöhter Hirndruck"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen, Torsade de pointes","Periphere Neuropathie (teils bleibend)","Aortenaneurysma und -dissektion, Herzklappenundichtigkeit","DRESS und akute generalisierte exanthematische Pustulose","Hyponatriämie (SIADH), Manie","Lang anhaltende, möglicherweise bleibende Nebenwirkungen an Sehnen, Muskeln, Gelenken, Nerven und Psyche"]},"schwangerschaft":"Vorsichtshalber nicht anwenden, da in Tierversuchen Gelenkknorpelschäden beim Jungtier auftraten. Augen- und Ohrentropfen nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; wegen möglicher Gelenkknorpelschäden beim Säugling während der systemischen Behandlung nicht stillen.","hinweise":["Nicht zusammen mit Milch, Joghurt oder mit Calcium angereicherten Säften allein einnehmen; Abstand zu Mineralstoff- und Eisenpräparaten sowie Antazida einhalten.","Bei Sehnenschmerzen, Kribbeln, Taubheit, plötzlichen Brust-, Bauch- oder Rückenschmerzen sofort absetzen und ärztliche Hilfe holen.","Starke Sonne und Solarium meiden; das Reaktionsvermögen kann eingeschränkt sein (Autofahren).","Kaffee wirkt stärker und länger."],"darreichung":["Filmtabletten","Suspension zum Einnehmen","Infusionslösung","Augentropfen","Ohrentropfen"]},"cisplatin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen, sodass sie sich nicht mehr teilen können. Cisplatin bildet in der Zelle reaktive Platinkomplexe, die die DNA-Stränge quer und innerhalb eines Strangs vernetzen. Dadurch werden DNA-Verdoppelung und Ablesung blockiert und der programmierte Zelltod ausgelöst. Betroffen sind vor allem sich schnell teilende Zellen; Cisplatin wird über die Niere ausgeschieden und reichert sich dort an.","nebenwirkungen":{"sehrHaeufig":["Nierenschädigung (Anstieg von Kreatinin und Harnstoff)","Übelkeit und Erbrechen","Knochenmarkhemmung (Leukopenie, Thrombozytopenie, Anämie)","Elektrolytstörungen (Mangel an Magnesium, Kalium, Natrium, Calcium)","Hyperurikämie (erhöhte Harnsäure)","Fieber"],"haeufig":["Hörverlust (v. a. hohe Töne) und Tinnitus (Ohrgeräusche)","Periphere Neuropathie (Kribbeln, Taubheit)","Infektionen, Sepsis","Herzrhythmusstörungen, Bradykardie","Venenentzündung an der Einstichstelle"],"gelegentlich":["Anaphylaxie (schwere allergische Reaktion)","Hypomagnesiämie mit Krämpfen"],"selten":["Akute Leukämie als Spätfolge","Krampfanfälle","Herzinfarkt"],"sehrSelten":["Herzstillstand"],"unbekannt":["Hämolytische Anämie","Thromboembolien","Sehstörungen, Sehnervenentzündung","Syndrom der inadäquaten ADH-Sekretion (SIADH, Natriummangel)","Posteriores reversibles Enzephalopathie-Syndrom (PRES)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, da Fruchtschäden möglich sind. Frauen und Männer sollen während und noch mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert; Cisplatin geht in die Muttermilch über.","hinweise":["Viel trinken, wie vom Behandlungsteam empfohlen – das schützt die Nieren.","Hörveränderungen, Ohrgeräusche, Kribbeln oder Taubheit in Händen und Füssen melden.","Keine Lebendimpfungen während und einige Monate nach der Therapie.","Spermien- bzw. Eizellkonservierung vor Therapiebeginn besprechen (mögliche Unfruchtbarkeit)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"citalopram":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Panikattacken, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Citalopram ist ein sehr selektiver Hemmer des Serotonin-Transporters und hat kaum Wirkung an anderen Rezeptoren. Es wird in der Leber über CYP2C19, CYP3A4 und CYP2D6 abgebaut; die Halbwertszeit beträgt etwa 1,5 Tage. Dosisabhängig verlängert es die QT-Zeit im EKG.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schlaflosigkeit","Kopfschmerzen","Übelkeit, Mundtrockenheit","Vermehrtes Schwitzen"],"haeufig":["Verminderter Appetit, Gewichtsabnahme","Unruhe, Angst, Nervosität, Verwirrtheit, ungewöhnliche Träume","Verminderte Libido, Orgasmus- und Ejakulationsstörungen, Impotenz","Zittern, Kribbeln, Schwindel, Konzentrationsstörungen","Ohrgeräusche (Tinnitus), Gähnen","Durchfall, Verstopfung, Erbrechen","Juckreiz, Muskel- und Gelenkschmerzen","Müdigkeit"],"gelegentlich":["Gewichtszunahme, Aggressivität, Halluzinationen, Manie","Ohnmacht (Synkope)","Erweiterte Pupillen (Mydriasis)","Langsamer oder schneller Puls","Nesselsucht, Hautausschlag, Haarausfall, Lichtempfindlichkeit, Hautblutungen (Purpura)","Harnverhalt","Starke Menstruationsblutungen","Wassereinlagerungen (Ödeme)"],"selten":["Hyponatriämie (Natriummangel)","Krampfanfälle, unwillkürliche Bewegungen","Blutungen","Leberentzündung (Hepatitis)","Fieber"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen inkl. Torsade de pointes","Serotoninsyndrom","Suizidgedanken und suizidales Verhalten","Thrombozytopenie, anaphylaktische Reaktionen, Angioödem","Magen-Darm-Blutungen, Nasenbluten, Blutergüsse","Akathisie (Bewegungsunruhe), Panikattacken, Zähneknirschen","Blutdruckabfall beim Aufstehen, Kaliummangel","Milchfluss (Galaktorrhö), Priapismus, Nachblutungen nach der Geburt"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung, nicht abrupt absetzen. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen (z. B. Atemprobleme, Trinkschwäche, Zittern) und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Citalopram geht in die Muttermilch über; ist eine Behandlung nötig, soll ein Abstillen erwogen werden.","hinweise":["Höchstdosis 40 mg pro Tag; bei Menschen über 65 Jahren, eingeschränkter Leberfunktion oder langsamem CYP2C19-Abbau höchstens 20 mg pro Tag (QT-Risiko).","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztlich abklären lassen.","Die Wirkung setzt nach 2–4 Wochen ein; nicht abrupt absetzen, sondern schrittweise ausschleichen.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"clarithromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clarithromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette; sein Hauptmetabolit 14-Hydroxy-Clarithromycin ist ebenfalls wirksam. Es wirkt gegen Streptokokken, Haemophilus, atypische Erreger (Mykoplasmen, Chlamydien, Legionellen), Helicobacter pylori und Mykobakterien. Clarithromycin hemmt das Abbauenzym CYP3A4 und den Transporter P-Glykoprotein stark und erhöht dadurch die Spiegel vieler anderer Medikamente.","nebenwirkungen":{"haeufig":["Geschmacksstörungen, Kopfschmerzen","Schlaflosigkeit","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, vermehrtes Schwitzen","Abweichende Leberwerte","Venenentzündung an der Infusionsstelle"],"gelegentlich":["Pilzinfektionen (Candidose), Scheideninfektion","Leukopenie, Neutropenie, Eosinophilie (Blutbildveränderungen)","Schwindel, Drehschwindel, Schläfrigkeit, Zittern, Angst","Hörstörungen, Tinnitus (Ohrensausen)","QT-Verlängerung im EKG, Herzklopfen","Gastritis, Verstopfung, Mundtrockenheit, Blähungen","Cholestase und Hepatitis (Leberentzündung)","Juckreiz, Nesselsucht, Muskelschmerzen"],"unbekannt":["Torsade de pointes, Kammertachykardie und Kammerflimmern","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Agranulozytose (starker Mangel an weissen Blutkörperchen), Thrombozytopenie","Anaphylaxie, Angioödem","Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Verwirrtheit, Halluzinationen, Psychosen, Krampfanfälle, Hörverlust","Rhabdomyolyse (Muskelzerfall), Nierenversagen, interstitielle Nephritis"]},"schwangerschaft":"Die Sicherheit ist nicht belegt; Tierversuche zeigen schädliche Wirkungen. Nur nach sorgfältiger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und Pilzbefall möglich. Nur nach ärztlicher Abwägung.","hinweise":["Vor Beginn alle anderen Medikamente angeben: Clarithromycin hat sehr viele, teils lebensgefährliche Wechselwirkungen.","Retardtabletten mit einer Mahlzeit und unzerkaut schlucken.","Bei Herzklopfen, Ohnmacht, Gelbsucht, dunklem Urin oder starkem Durchfall sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Retardtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung"]},"clindamycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clindamycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und hemmt die Peptidkettenbildung; es wirkt vorwiegend bakteriostatisch gegen grampositive Kokken (Staphylokokken, Streptokokken) und Anaerobier. Es dringt gut in Knochen und Gewebe ein und hemmt die Toxinbildung von Streptokokken und Staphylokokken. Gegen Enterokokken und die meisten gramnegativen Keime wirkt es nicht.","nebenwirkungen":{"haeufig":["Durchfall, Bauchschmerzen","Pseudomembranöse Kolitis (schwere Dickdarmentzündung durch Clostridioides difficile)","Fleckiger Hautausschlag","Abweichende Leberwerte","Venenentzündung bei Infusion","Bei Anwendung auf der Haut: Trockenheit, Rötung, Brennen; bei Vaginalcreme: Scheidenpilz"],"gelegentlich":["Übelkeit, Erbrechen","Geschmacksstörungen","Nesselsucht"],"selten":["Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)","Juckreiz"],"unbekannt":["Agranulozytose, Neutropenie, Thrombozytopenie (Blutbildschäden)","Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Gelbsucht","Speiseröhrenentzündung oder -geschwür bei Kapseln","Akute Nierenschädigung"]},"schwangerschaft":"Im 2. und 3. Drittel zeigten Studien kein erhöhtes Fehlbildungsrisiko; für das 1. Drittel sind die Daten begrenzt. Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; die Anwendung auf der Haut gilt als vertretbar.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall, Pilzbefall und selten blutiger Stuhl möglich. Nach ärztlicher Abwägung, Kind beobachten.","hinweise":["Kapseln aufrecht mit einem vollen Glas Wasser schlucken (Gefahr einer Speiseröhrenreizung).","Bei starkem, anhaltendem oder blutigem Durchfall – auch Wochen nach der Behandlung – sofort ärztliche Hilfe holen; keine stopfenden Mittel wie Loperamid nehmen.","Vaginalcreme kann Kondome und Diaphragmen aus Latex beschädigen.","Akne-Kombinationen mit Benzoylperoxid können Textilien und Haare bleichen."],"darreichung":["Kapseln","Injektions- und Infusionslösung","Lösung und Gel zum Auftragen auf die Haut","Vaginalcreme"]},"clindamycin-benzoylperoxid":{"wirkmechanismus":"Bekämpft die an der Akne beteiligten Bakterien, wirkt entzündungshemmend und löst Verhornungen. Clindamycin hemmt als Lincosamid-Antibiotikum die bakterielle Eiweissbildung an der 50S-Untereinheit der Ribosomen und wirkt gegen Cutibacterium acnes. Benzoylperoxid setzt Sauerstoffradikale frei, tötet so Bakterien ab und wirkt leicht schälend (keratolytisch). Weil Benzoylperoxid unspezifisch wirkt, vermindert die Kombination die Entstehung Clindamycin-resistenter Bakterien.","nebenwirkungen":{"sehrHaeufig":["Rötung, Schuppung und Trockenheit der Haut an der Auftragsstelle (meist leicht)"],"haeufig":["Brennen, Schmerzen und Juckreiz an der Auftragsstelle","Kopfschmerzen","Lichtempfindlichkeit (Photosensibilität)"],"gelegentlich":["Kribbeln der Haut (Parästhesien)","Dermatitis, Verschlechterung der Akne"],"unbekannt":["Darmentzündung durch Antibiotika (pseudomembranöse Kolitis), blutiger Durchfall, Bauchschmerzen","Allergische Reaktionen bis zur Anaphylaxie, Gesichtsschwellung","Nesselsucht (Urtikaria)"]},"schwangerschaft":"Nur wenig Erfahrungen; nur nach ärztlicher Abwägung anwenden, wenn klar notwendig.","stillzeit":"Nur nach ärztlicher Abwägung; nicht auf die Brust auftragen, damit der Säugling nicht in Kontakt mit dem Gel kommt.","hinweise":["Einmal täglich abends dünn auf die gereinigte, trockene Haut auftragen; danach die Hände waschen.","Benzoylperoxid bleicht Haare und Textilien (Kleidung, Handtücher, Bettwäsche) – Kontakt vermeiden.","Ohne ärztliche Neubeurteilung nicht länger als 12 Wochen anwenden (Resistenzgefahr).","Sonne und Solarium meiden, Sonnenschutz verwenden."],"darreichung":["Gel"]},"clioquinol":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien und Pilzen auf der Haut und im Gehörgang. Clioquinol (5-Chlor-7-iod-8-hydroxychinolin) bindet Metallionen wie Eisen, Zink und Kupfer, die Mikroorganismen für ihre Enzyme benötigen, und wirkt dadurch bakteriostatisch und fungistatisch, u. a. gegen grampositive Bakterien sowie Hefe- und Hautpilze. In der Kombination dämpft das Kortikosteroid Flumetason Entzündung und Juckreiz. Bei grossflächiger Anwendung, auf verletzter Haut oder unter Verbänden kann Clioquinol durch die Haut ins Blut gelangen.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Allergische Kontaktdermatitis","Gelbliche Verfärbung von Haut, Haaren und Nägeln","Hautatrophie (Hautverdünnung), erweiterte Äderchen, Dehnungsstreifen bei längerer Anwendung (Kortikosteroid-Anteil)","Hellere Hautstellen (Hypopigmentierung)","Unterdrückung der Nebennierenrinde bei grossflächiger Anwendung (Kortikosteroid-Anteil)"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach strenger ärztlicher Abwägung, kleinflächig und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob Clioquinol in die Muttermilch übergeht; nur nach ärztlicher Abwägung und nicht im Brustbereich anwenden.","hinweise":["Färbt Haut, Haare, Kleidung und Wäsche gelb; Flecken in Textilien lassen sich oft nicht auswaschen.","Nicht grossflächig und nicht unter luftdichten Verbänden anwenden; die Behandlung auf die verordnete Dauer begrenzen.","Vor Schilddrüsenuntersuchungen die Anwendung angeben, weil das Jod Messwerte verfälschen kann."],"darreichung":["Creme","Ohrentropfen"]},"clobetasol":{"wirkmechanismus":"Hemmt Entzündung, Juckreiz und übermässige Zellteilung in der Haut sehr stark. Clobetasolpropionat bindet an den Glukokortikoid-Rezeptor der Hautzellen und unterdrückt die Bildung entzündungsfördernder Botenstoffe; zusätzlich verengt es die kleinen Hautgefässe und bremst die Vermehrung der Hautzellen (antiproliferative Wirkung). Es gehört zu den stärksten äusserlich angewendeten Kortikosteroiden (Klasse IV) und kann bei grossflächiger oder langer Anwendung in relevanter Menge in den Körper gelangen.","nebenwirkungen":{"haeufig":["Juckreiz","Brennen oder Schmerzen der Haut an der Auftragsstelle"],"gelegentlich":["Hautverdünnung (Atrophie)","Dehnungsstreifen (Striae)","Erweiterte Äderchen (Teleangiektasien)"],"sehrSelten":["Kortison-Wirkungen im ganzen Körper: Cushing-Syndrom, Nebennierenschwäche, erhöhter Blutzucker, Bluthochdruck, Wachstumsverzögerung bei Kindern","Grauer und grüner Star (Katarakt, Glaukom)","Opportunistische Hautinfektionen","Allergische Kontaktdermatitis und andere Überempfindlichkeitsreaktionen","Verschlechterung der Psoriasis, pustulöse Psoriasis","Pigmentveränderungen, vermehrte Behaarung, Akne, rosazeaartige Hautentzündung"],"unbekannt":["Verschwommenes Sehen (Chorioretinopathie)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, so kurz und kleinflächig wie möglich; in Tierversuchen traten nach Anwendung starker Kortikosteroide Fehlbildungen auf.","stillzeit":"Nach Abwägung kurzfristig und kleinflächig möglich; nicht auf die Brust auftragen.","hinweise":["Höchstens 50 g Creme oder Salbe pro Woche und in der Regel nicht länger als 4 Wochen anwenden.","Dünn auftragen und danach die Hände waschen; luftdichte Verbände nur auf ärztliche Anweisung.","Nach Besserung nicht abrupt absetzen, sondern ausschleichen oder auf ein schwächeres Präparat wechseln.","Shampoo (Clobex) auf die trockene Kopfhaut auftragen, 15 Minuten einwirken lassen und gründlich ausspülen."],"darreichung":["Creme","Salbe","Lösung für die Kopfhaut","Schaum","Shampoo"]},"clomifen":{"wirkmechanismus":"Bewirkt, dass die Hirnanhangsdrüse mehr eisprungfördernde Hormone ausschüttet. Clomifen besetzt als nichtsteroidaler Östrogenrezeptor-Modulator die Östrogenrezeptoren im Hypothalamus und hebt so die hemmende Rückkopplung durch körpereigenes Östrogen auf. Dadurch steigt die Ausschüttung von GnRH und in der Folge von FSH und LH, was die Reifung eines Eibläschens (Follikel) und den Eisprung auslöst.","nebenwirkungen":{"sehrHaeufig":["Vergrösserung der Eierstöcke","Hitzewallungen"],"haeufig":["Bauch- und Unterleibsbeschwerden, Blähgefühl","Übelkeit, Erbrechen","Brustspannen","Sehstörungen (Verschwommensehen, Flimmern, Lichtblitze)","Kopfschmerzen","Zwischenblutungen"],"unbekannt":["Ovarielles Überstimulationssyndrom (OHSS)","Schwindel, Nervosität, Schlafstörungen, depressive Verstimmung","Hautausschlag, Nesselsucht, Haarausfall","Bauchspeicheldrüsenentzündung bei stark erhöhten Triglyceriden"]},"schwangerschaft":"Kontraindiziert. Vor jedem Behandlungszyklus muss eine Schwangerschaft ausgeschlossen werden.","stillzeit":"Nicht anwenden; Clomifen kann zudem die Milchbildung vermindern.","hinweise":["Behandlung nur unter fachärztlicher Kontrolle mit Ultraschall; in der Regel nicht mehr als 6 Zyklen.","Bei Sehstörungen sofort absetzen, augenärztlich abklären lassen und nicht Auto fahren.","Starke Bauchschmerzen, Blähbauch oder rasche Gewichtszunahme können auf eine Überstimulation hinweisen – sofort ärztlich melden.","Die Wahrscheinlichkeit für Zwillinge oder Mehrlinge ist erhöht."],"darreichung":["Tabletten"]},"clomipramin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Zwangsgedanken und Angst, indem es die Konzentration von Botenstoffen im Gehirn erhöht. Clomipramin hemmt besonders stark die Wiederaufnahme von Serotonin und – vor allem über sein Abbauprodukt Desmethylclomipramin – auch von Noradrenalin in die Nervenzellen. Zusätzlich blockiert es Muskarin-, Histamin-H1- und Alpha-1-Rezeptoren, was Nebenwirkungen wie Mundtrockenheit, Müdigkeit und Blutdruckabfall erklärt. Die stimmungsaufhellende Wirkung setzt meist erst nach 2–4 Wochen ein.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Müdigkeit, Unruhe","Schwindel, Zittern (Tremor), Kopfschmerzen, Muskelzuckungen (Myoklonien)","Mundtrockenheit, Verstopfung, Übelkeit","Vermehrtes Schwitzen","Sehstörungen (Akkommodationsstörungen, verschwommenes Sehen)","Störungen beim Wasserlassen","Appetit- und Gewichtszunahme","Libido- und Potenzstörungen"],"haeufig":["Verwirrtheit, Desorientierung, Halluzinationen (vor allem bei älteren Menschen)","Angst, Agitiertheit, Schlafstörungen, Albträume, Manie, Aggressivität","Konzentrations- und Gedächtnisstörungen, Sprachstörungen, Kribbeln (Parästhesien)","Herzrasen, Herzklopfen, Blutdruckabfall beim Aufstehen (orthostatische Hypotonie), EKG-Veränderungen","Erbrechen, Bauchschmerzen, Durchfall, Appetitlosigkeit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Lichtempfindlichkeit","Ohrgeräusche (Tinnitus), Geschmacksstörungen, Milchfluss (Galaktorrhö)"],"gelegentlich":["Krampfanfälle","Gangunsicherheit (Ataxie)","Herzrhythmusstörungen","Blutdruckanstieg"],"sehrSelten":["Agranulozytose (starke Verminderung bestimmter weisser Blutkörperchen) und andere Blutbildveränderungen","Hyponatriämie durch inadäquate ADH-Sekretion (SIADH)","Akutes Glaukom","Leberentzündung (Hepatitis)","Reizleitungsstörungen des Herzens, QT-Verlängerung, Torsade de pointes","Anaphylaxie, Ödeme, Haarausfall","Malignes neuroleptisches Syndrom","Harnverhalt, allergische Lungenentzündung (Alveolitis)"],"unbekannt":["Serotoninsyndrom","Extrapyramidale Störungen (z. B. Akathisie)","Suizidgedanken und suizidales Verhalten","Erhöhtes Risiko für Knochenbrüche"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt können beim Neugeborenen Entzugs- und Anpassungsstörungen auftreten (Atemprobleme, Zittern, Trinkschwäche, Krampfanfälle).","stillzeit":"Clomipramin geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Die stimmungsaufhellende Wirkung setzt meist erst nach 2–4 Wochen ein, Nebenwirkungen wie Mundtrockenheit und Müdigkeit dagegen früh.","Nicht abrupt absetzen (Übelkeit, Kopfschmerzen, Unruhe, Schlafstörungen), sondern schrittweise nach ärztlicher Anleitung reduzieren.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Vor und während der Behandlung EKG und Blutdruck, bei Bedarf Blutbild und Leberwerte kontrollieren; Haut vor starker Sonne schützen."],"darreichung":["Dragées","Retardtabletten"]},"clonazepam":{"wirkmechanismus":"Dämpft die Erregbarkeit von Nervenzellen und verhindert so Krampfanfälle; wirkt zudem beruhigend und muskelentspannend. Clonazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung des Botenstoffs GABA, indem es die Öffnungshäufigkeit des Chloridkanals erhöht. Es wird in der Leber unter Beteiligung von CYP3A4 abgebaut und hat eine lange Halbwertszeit (etwa 30–40 Stunden).","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit, verlangsamte Reaktionen (besonders zu Behandlungsbeginn)","Muskelschwäche, Schwindel, Gang- und Koordinationsstörungen (Ataxie)","Konzentrations- und Gedächtnisstörungen","Paradoxe Reaktionen (Unruhe, Reizbarkeit, Aggression, Halluzinationen), besonders bei Kindern und älteren Menschen","Vermehrter Speichel- und Bronchialschleim bei Säuglingen und Kleinkindern","Atemdepression (besonders bei Injektion)","Abhängigkeit und Entzugssymptome bis zu Krampfanfällen beim abrupten Absetzen","Zunahme der Anfallshäufigkeit bei bestimmten Epilepsieformen"]},"schwangerschaft":"Nur bei zwingender Indikation nach ärztlicher Abwägung; bei Einnahme in der Spätschwangerschaft drohen beim Neugeborenen Trinkschwäche, Muskelschlaffheit, Atemprobleme und Entzugssymptome.","stillzeit":"Geht in die Muttermilch über; Stillen wird nicht empfohlen bzw. nur unter ärztlicher Überwachung des Kindes auf Schläfrigkeit und Trinkschwäche.","hinweise":["Nicht abrupt absetzen – Gefahr von Entzugssymptomen und Krampfanfällen; schrittweise nach ärztlicher Anweisung ausschleichen.","Kein Alkohol; Fahrtüchtigkeit ist besonders zu Beginn deutlich eingeschränkt.","Bei längerer Anwendung kann sich die Wirkung abschwächen und eine Abhängigkeit entstehen."],"darreichung":["Tabletten","Tropfen (Lösung zum Einnehmen)","Injektionslösung"]},"clonidin":{"wirkmechanismus":"Senkt den Blutdruck, indem es im Gehirn die Signale des sympathischen Nervensystems an Herz und Gefässe drosselt. Clonidin stimuliert Alpha-2-Rezeptoren und Imidazolin-Rezeptoren im Hirnstamm; dadurch sinken die Ausschüttung von Noradrenalin, der Gefässwiderstand und die Herzfrequenz. Die zentrale Wirkung erklärt auch Müdigkeit und Mundtrockenheit. Nach plötzlichem Absetzen kann der Sympathikus überschiessend reagieren (Rebound-Hochdruck).","nebenwirkungen":{"sehrHaeufig":["Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Schwindel","Müdigkeit, Sedierung","Mundtrockenheit"],"haeufig":["Depression, Schlafstörungen","Kopfschmerzen","Verstopfung, Übelkeit, Erbrechen","Schmerzen der Speicheldrüsen","Erektionsstörungen","Erschöpfung"],"gelegentlich":["Albträume, Wahnvorstellungen, Halluzinationen","Kribbeln (Parästhesien)","Sinusbradykardie","Raynaud-Syndrom (Weissfinger)","Juckreiz, Hautausschlag, Nesselsucht","Unwohlsein"],"selten":["AV-Block","Verminderter Tränenfluss","Darmlähmung (Pseudoobstruktion des Dickdarms)","Gynäkomastie (Brustvergrösserung beim Mann)","Haarausfall","Erhöhter Blutzucker"],"unbekannt":["Verwirrtheit","Verminderte Libido","Akkommodationsstörungen (Probleme beim Scharfsehen)","Bradyarrhythmie"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Clonidin gelangt zum Kind und kann beim Neugeborenen Blutdruck und Puls senken.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Nie abrupt absetzen – sonst drohen starker Blutdruckanstieg, Herzrasen und Unruhe; immer über einige Tage ausschleichen.","Alkohol verstärkt die Müdigkeit; Fahrtüchtigkeit kann besonders zu Beginn eingeschränkt sein.","Langsam aufstehen, um Schwindel durch Blutdruckabfall zu vermeiden."],"darreichung":["Tabletten","Injektionslösung"]},"clopamid":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere und senkt dadurch den Blutdruck. Clopamid hemmt im frühen distalen Nierentubulus den Natrium-Chlorid-Kotransporter, sodass mehr Natrium, Chlorid und Wasser ausgeschieden werden; dabei gehen auch Kalium und Magnesium verloren, während Calcium zurückgehalten wird. Bei Dauerbehandlung trägt eine Abnahme des Gefässwiderstands zur Blutdrucksenkung bei.","nebenwirkungen":{"unbekannt":["Hypokaliämie (Kaliummangel), Hyponatriämie (Natriummangel), Magnesiummangel","Hyperurikämie (erhöhte Harnsäure), Gichtanfälle","Hyperglykämie (erhöhter Blutzucker), erhöhte Blutfette","Schwindel, Blutdruckabfall beim Aufstehen, Müdigkeit","Magen-Darm-Beschwerden, Appetitlosigkeit","Lichtempfindlichkeit der Haut, Hautausschlag","Potenzstörungen","Blutbildveränderungen (Thrombozytopenie, Agranulozytose), Pankreatitis"]},"schwangerschaft":"Nicht empfohlen: Thiazid-Diuretika können die Durchblutung der Plazenta vermindern und beim Neugeborenen Elektrolytstörungen und Blutplättchenmangel verursachen; nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen – nicht empfohlen.","hinweise":["Morgens einnehmen, damit der vermehrte Harndrang die Nachtruhe nicht stört.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren.","Haut vor starker Sonne schützen.","Das Kombinationspräparat (mit dem Betablocker Pindolol) nicht abrupt absetzen."],"darreichung":["Tabletten (Kombinationspräparat)"]},"clopidogrel":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Arterien bilden. Clopidogrel ist eine unwirksame Vorstufe (Prodrug), die in der Leber vor allem über das Enzym CYP2C19 in einen aktiven Metaboliten umgewandelt wird. Dieser blockiert den ADP-Rezeptor P2Y12 der Blutplättchen irreversibel und hemmt damit deren Aktivierung. Die Hemmung hält für die ganze Lebensdauer der Plättchen (7–10 Tage) an. Bei genetisch langsamer CYP2C19-Aktivität entsteht weniger Wirkstoff, die Wirkung ist dann schwächer.","nebenwirkungen":{"haeufig":["Blutergüsse (Hämatome), Hautblutungen","Nasenbluten","Magen-Darm-Blutungen","Durchfall, Bauchschmerzen, Verdauungsbeschwerden","Nachblutung an Punktionsstellen"],"gelegentlich":["Hirnblutung (teils tödlich)","Verminderung von Blutplättchen und weissen Blutkörperchen, Eosinophilie","Kopfschmerzen, Schwindel, Kribbeln","Magen- und Zwölffingerdarmgeschwüre, Gastritis, Übelkeit, Erbrechen, Verstopfung","Augenblutungen","Hautausschlag, Juckreiz","Blut im Urin"],"selten":["Neutropenie, auch schwere (Mangel an weissen Blutkörperchen)","Drehschwindel","Blutungen im hinteren Bauchraum (retroperitoneal)","Gynäkomastie (Brustvergrösserung beim Mann)"],"sehrSelten":["Thrombotisch-thrombozytopenische Purpura (TTP)","Agranulozytose, aplastische Anämie, Panzytopenie, schwere Thrombozytopenie","Erworbene Hämophilie A","Anaphylaktoide Reaktionen, Serumkrankheit, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Akutes Leberversagen, Hepatitis, Pankreatitis","Schwere, auch tödliche Blutungen","Interstitielle oder eosinophile Pneumonie, Bronchospasmus"],"unbekannt":["Insulin-Autoimmunsyndrom mit schwerer Unterzuckerung","Kounis-Syndrom (allergisch ausgelöste Brustenge)","Kreuzallergie mit anderen Thienopyridinen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; vorsichtshalber in der Schwangerschaft nicht anwenden, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Im Tierversuch Übergang in die Muttermilch; während der Behandlung nicht stillen.","hinweise":["Nicht eigenmächtig absetzen – besonders nach Stent-Einlage drohen Stentverschluss und Herzinfarkt.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 7 Tage vorher) nur nach ärztlicher Anordnung.","Als Magenschutz eignet sich eher Pantoprazol als Omeprazol oder Esomeprazol.","Bei Fieber, Schwäche, Verwirrtheit, Gelbsucht oder punktförmigen Hautblutungen sofort ärztliche Hilfe holen (TTP)."],"darreichung":["Filmtabletten"]},"clotrimazol":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen, indem es den Aufbau ihrer Zellmembran stört. Clotrimazol blockiert das pilzeigene Enzym Lanosterol-14-alpha-Demethylase (ein Cytochrom-P450-Enzym) und damit die Bildung von Ergosterol, dem wichtigsten Baustein der Pilzzellmembran. Die Membran wird durchlässig; in niedriger Konzentration wirkt Clotrimazol wachstumshemmend (fungistatisch), in hoher abtötend (fungizid). Es wirkt gegen Dermatophyten, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien (z. B. Erreger des Erythrasmas). Auf Haut oder Schleimhaut aufgetragen gelangt nur sehr wenig Wirkstoff ins Blut.","nebenwirkungen":{"unbekannt":["Haut: Rötung, Brennen, Stechen, Juckreiz, Reizung, Schuppung, Bläschen, Schwellung","Scheide: Brennen, Juckreiz, Rötung, Schwellung, Beschwerden, Ausschlag","Unterleibsschmerzen, vaginale Blutungen","Allergische Reaktionen bis zu Kreislaufkollaps (Synkope, Blutdruckabfall), Atemnot, Nesselsucht"]},"schwangerschaft":"Kann nach ärztlicher Rücksprache angewendet werden (sehr geringe Aufnahme ins Blut). Vaginaltabletten in der Schwangerschaft ohne Applikator einführen.","stillzeit":"Anwendung möglich; nicht im Brustbereich auftragen bzw. die Haut vor dem Stillen gründlich reinigen.","hinweise":["Hautpilz: nach Abklingen der Beschwerden noch etwa 2 Wochen weiterbehandeln, um Rückfälle zu vermeiden.","Scheidenpilz: abends tief in die Scheide einführen; die Behandlung nicht während der Menstruation durchführen. Den Partner bei Beschwerden mitbehandeln.","Latex-Kondome und Diaphragmen sind während und bis mindestens 5 Tage nach vaginaler Anwendung nicht sicher.","Nicht in die Augen bringen und nicht einnehmen; Handtücher und Wäsche häufig wechseln und heiss waschen."],"darreichung":["Creme","Lösung","Paste","Vaginaltabletten","Vaginalcreme"]},"clozapin":{"wirkmechanismus":"Lindert psychotische Beschwerden auch dann, wenn andere Antipsychotika nicht wirken, und verursacht dabei kaum Bewegungsstörungen. Clozapin blockiert Dopamin-Rezeptoren (v. a. D4, schwächer D2) sowie stark Serotonin-5-HT2A-Rezeptoren. Zusätzlich hemmt es Histamin-H1-, Muskarin- und Alpha-1-Rezeptoren, was Müdigkeit, Verstopfung und Blutdruckabfall erklärt. Es wird hauptsächlich über CYP1A2 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Sedierung","Schwindel","Tachykardie (Herzrasen)","Verstopfung","Hypersalivation (vermehrter Speichelfluss, v. a. nachts)"],"haeufig":["Leukopenie, Neutropenie, Eosinophilie","Gewichtszunahme","Krampfanfälle, Muskelzuckungen","Kopfschmerzen, Zittern, Muskelsteife, Sitzunruhe","Orthostatische Hypotonie, Ohnmacht, Bluthochdruck, EKG-Veränderungen","Übelkeit, Erbrechen, Mundtrockenheit, Appetitlosigkeit","Erhöhte Leberwerte","Harninkontinenz, Harnverhalt, meist harmlose Temperaturerhöhung zu Beginn"],"gelegentlich":["Agranulozytose (lebensbedrohlicher Mangel an weissen Blutkörperchen)","Malignes neuroleptisches Syndrom","Sprachstörungen","Stürze"],"selten":["Myokarditis und Perikarditis (Entzündung von Herzmuskel oder Herzbeutel), Herzrhythmusstörungen","Kreislaufkollaps","Erhöhter Blutzucker, Diabetes","Venöse Thromboembolie","Aspiration, Atemdepression","Verwirrtheit, Delir, Unruhe","Hepatitis, Pankreatitis","Anämie"],"sehrSelten":["Kardiomyopathie, Herzstillstand","Darmlähmung, Darmverschluss","Fulminante Lebernekrose (akutes Leberversagen)","Thrombozytopenie","Diabetische Ketoazidose, schwere Hyperglykämie","Spätdyskinesien","Priapismus","Interstitielle Nephritis"],"unbekannt":["QT-Verlängerung","Herzinfarkt","Lungenentzündung"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach sorgfältiger Abwägung. Bei Einnahme im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich; beim Wechsel von anderen Antipsychotika kann sich die Fruchtbarkeit normalisieren – wirksam verhüten.","stillzeit":"Clozapin geht in die Muttermilch über. Nicht stillen.","hinweise":["Blutbild in den ersten 18 Wochen wöchentlich, danach mindestens monatlich; bei Fieber, Halsschmerzen oder grippeähnlichen Beschwerden sofort ärztliche Kontrolle.","Verstopfung früh behandeln und melden – Gefahr einer lebensbedrohlichen Darmlähmung.","Rauchbeginn, Rauchstopp oder eine Änderung des Kaffeekonsums ärztlich mitteilen.","Nach einem Unterbruch von mehr als 2 Tagen nicht mit der alten Dosis weiterfahren, sondern neu einschleichen."],"darreichung":["Tabletten"]},"codein":{"wirkmechanismus":"Dämpft den Hustenreflex im Hirnstamm und lindert Schmerzen. Codein ist selbst nur ein schwacher Agonist am μ-Opioidrezeptor; seine schmerzstillende Wirkung beruht vor allem auf Morphin, das in der Leber über das Enzym CYP2D6 aus einem kleinen Teil der Dosis gebildet wird. Wie viel Morphin entsteht, hängt vom CYP2D6-Erbgut ab: ultraschnelle Metabolisierer bilden gefährlich viel Morphin, langsame Metabolisierer kaum.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen (v. a. zu Beginn)","Obstipation (Verstopfung)"],"haeufig":["Kopfschmerzen","Schläfrigkeit, Benommenheit"],"gelegentlich":["Schlafstörungen","Kurzatmigkeit","Mundtrockenheit","Juckreiz, Hautrötung, Nesselsucht","Ohrensausen (Tinnitus)"],"selten":["Schwere allergische Reaktionen, einschliesslich Stevens-Johnson-Syndrom"],"unbekannt":["Atemdepression (gefährlich abgeflachte Atmung), v. a. bei hohen Dosen oder ultraschnellem CYP2D6-Stoffwechsel","Abhängigkeit und Entzugserscheinungen bei längerer Einnahme","Blutdruckabfall, Ohnmacht","Euphorie oder Verstimmung","Krampf der Gallenwege"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung und kurzfristig. Einnahme kurz vor der Geburt kann beim Neugeborenen Atemdämpfung, längere Einnahme Entzugssymptome verursachen.","stillzeit":"Kontraindiziert: Codein und Morphin gehen in die Muttermilch über; bei ultraschnellem Stoffwechsel der Mutter ist eine lebensgefährliche Atemdämpfung beim Säugling möglich.","hinweise":["Beeinträchtigt die Fahrtüchtigkeit; keinen Alkohol trinken.","Nur kurzfristig und nur bei trockenem Reizhusten anwenden, nicht bei Husten mit viel Schleim.","Kann abhängig machen – nicht länger und nicht höher dosiert einnehmen als verordnet.","Bei Atemnot, starker Schläfrigkeit, sehr engen Pupillen oder Verwirrtheit (Zeichen einer Überdosierung) sofort den Notruf (144) wählen."],"darreichung":["Tabletten","Tropfen","Sirup","Brausetabletten (Kombipräparat)"]},"colchicin":{"wirkmechanismus":"Hemmt die Entzündung im Gelenk, indem es weisse Blutkörperchen daran hindert, einzuwandern und Entzündungsstoffe freizusetzen. Colchicin bindet an Tubulin und hemmt den Aufbau der Mikrotubuli; dadurch werden Beweglichkeit, Zellteilung und Aktivierung der neutrophilen Granulozyten sowie das NLRP3-Inflammasom gebremst. Es senkt die Harnsäure nicht. Abgebaut und ausgeschieden wird es über CYP3A4 und P-Glykoprotein; die therapeutische Breite ist sehr gering.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit, Erbrechen","Bauchschmerzen"],"unbekannt":["Knochenmarkschädigung mit Agranulozytose, Thrombozytopenie oder aplastischer Anämie","Periphere Neuropathie (Nervenschädigung)","Myopathie (Muskelerkrankung), Rhabdomyolyse (Muskelzerfall)","Magen-Darm-Blutungen","Leberschäden","Haarausfall, Hautausschlag","Störung der Spermienbildung, Ausbleiben der Regelblutung"]},"schwangerschaft":"Kontraindiziert; einzige Ausnahme ist das familiäre Mittelmeerfieber, bei dem die Behandlung nach ärztlicher Abwägung weitergeführt werden kann.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Die verordnete Höchstdosis beim akuten Anfall nicht überschreiten; schon geringe Überdosen können tödlich sein. Für Kinder unerreichbar aufbewahren.","Bei Durchfall, Übelkeit oder Erbrechen (erste Vergiftungszeichen) Einnahme stoppen und ärztlichen Rat einholen.","Keinen Grapefruitsaft trinken.","Bei Langzeitbehandlung Blutbild sowie Nieren- und Leberwerte regelmässig kontrollieren."],"darreichung":["Dragées (überzogene Tabletten)"]},"colecalciferol-vitamin-d3":{"wirkmechanismus":"Stellt dem Körper Vitamin D zur Verfügung, das er für die Aufnahme von Calcium und gesunde Knochen braucht. Colecalciferol ist eine Vorstufe: In der Leber wird es zu 25-Hydroxyvitamin D (Calcifediol, dem Speicher- und Messwert im Blut) und in der Niere zu 1,25-Dihydroxyvitamin D (Calcitriol, der aktiven Form) umgewandelt. Calcitriol steigert über den Vitamin-D-Rezeptor die Aufnahme von Calcium und Phosphat im Darm, fördert die Mineralisierung des Knochens und bremst die Ausschüttung von Parathormon. Weil Vitamin D im Fettgewebe gespeichert wird, wirkt es lange nach und kann auch wöchentlich oder monatlich gegeben werden.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Juckreiz, Hautausschlag, Nesselsucht"],"unbekannt":["Bei Überdosierung: Übelkeit, Erbrechen, Verstopfung, Appetitlosigkeit, starker Durst, vermehrtes Wasserlassen, Muskelschwäche, Verwirrtheit","Nierensteine und Verkalkungen in Niere und Gefässen bei langdauernder Überdosierung"]},"schwangerschaft":"In den empfohlenen Dosen erlaubt und bei Mangel sinnvoll; Überdosierungen vermeiden, da eine anhaltende Hyperkalzämie dem Kind schaden kann.","stillzeit":"In üblichen Dosen erlaubt; Vitamin D geht in die Muttermilch über, ersetzt aber nicht die Vitamin-D-Gabe an den Säugling.","hinweise":["Am besten zu einer Mahlzeit einnehmen, da fetthaltige Speisen die Aufnahme verbessern.","Hoch dosierte Wochen- oder Monatsdosen nicht mit täglichen Präparaten verwechseln und nicht mehrere Vitamin-D-Präparate kombinieren.","Bei hohen Dosen, Nierenkrankheit oder gleichzeitiger Calciumeinnahme Calcium im Blut kontrollieren lassen.","In der Schweiz wird für Säuglinge und Kleinkinder in den ersten 3 Lebensjahren eine tägliche Vitamin-D-Gabe empfohlen."],"darreichung":["Tropfen","Kapseln","Tabletten","Ampullen (hoch dosiert)"]},"corifollitropin-alfa":{"wirkmechanismus":"Regt mit einer einzigen Injektion eine Woche lang die Reifung mehrerer Eibläschen (Follikel) an. Corifollitropin alfa ist ein gentechnisch hergestelltes FSH, an dessen Beta-Kette ein Teil des hCG-Moleküls (C-terminales Peptid) angehängt ist; dadurch wirkt es etwa doppelt so lange wie FSH. Es bindet an den FSH-Rezeptor und ersetzt in den ersten 7 Tagen der Stimulation die täglichen FSH-Spritzen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit","Müdigkeit","Beckenschmerzen und -beschwerden","Brustbeschwerden (Schmerzen, Spannen)","Ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Schwindel, Hitzewallungen","Blähbauch, Erbrechen, Durchfall, Verstopfung","Rückenschmerzen","Stieldrehung eines Eierstocks (Ovarialtorsion), vorzeitiger Eisprung","Schmerzen an der Einstichstelle","Reizbarkeit, Stimmungsschwankungen","Erhöhte Leberwerte"],"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Hautausschlag)","Thromboembolie"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Wird einmalig zu Beginn der Stimulation unter die Haut gespritzt; ab Tag 8 folgt bei Bedarf tägliches FSH.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung in Fertigspritze"]},"covid-19-impfstoff-mrna":{"wirkmechanismus":"Gibt den Körperzellen eine Bauanleitung für das Spike-Protein des Coronavirus, gegen das das Immunsystem dann Abwehr aufbaut. Die modifizierte mRNA ist in Lipid-Nanopartikel verpackt, wird in Zellen am Injektionsort und in Lymphknoten abgelesen und innerhalb weniger Tage abgebaut. Sie gelangt nicht in den Zellkern und verändert das Erbgut nicht. Das gebildete Spike-Protein löst Antikörper und T-Zell-Antworten aus.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Schwellung an der Einstichstelle","Müdigkeit, Kopfschmerzen","Muskel- und Gelenkschmerzen","Schüttelfrost, Fieber","Übelkeit, Erbrechen, Durchfall","Lymphknotenschwellung in der Achsel"],"haeufig":["Rötung an der Einstichstelle, auch verzögert nach einigen Tagen","Hautausschlag"],"gelegentlich":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht)","Schlaflosigkeit, Appetitlosigkeit","Starkes Schwitzen, Nachtschweiss","Schwindel"],"selten":["Akute Gesichtslähmung (Fazialisparese)","Gesichtsschwellung bei Personen mit kosmetischen Hautfüllern"],"sehrSelten":["Myokarditis und Perikarditis (Herzmuskel- und Herzbeutelentzündung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Erythema multiforme (Hautreaktion)","Ausgedehnte Schwellung der geimpften Gliedmasse","Starke Menstruationsblutungen","Kribbeln oder Taubheitsgefühl"]},"schwangerschaft":"Kann während der Schwangerschaft angewendet werden; grosse Beobachtungsstudien zeigen kein erhöhtes Risiko für Mutter oder Kind.","stillzeit":"Kann während der Stillzeit angewendet werden.","hinweise":["Nach der Impfung 15 Minuten (nach früherer schwerer allergischer Reaktion 30 Minuten) unter Beobachtung bleiben.","Bei Brustschmerzen, Atemnot oder Herzklopfen in den Tagen nach der Impfung sofort ärztliche Hilfe holen.","Die Impfstoffe werden regelmässig an neue Varianten angepasst; Impfempfehlung (meist im Herbst) für die eigene Situation in der Apotheke oder ärztlich klären."],"darreichung":["Injektionsdispersion in Durchstechflasche oder Fertigspritze"]},"cyanocobalamin":{"wirkmechanismus":"Ersetzt fehlendes Vitamin B12, das für die Blutbildung und die Nerven unentbehrlich ist. Cyanocobalamin wird im Körper in die aktiven Formen Methylcobalamin und Adenosylcobalamin umgewandelt. Diese sind Coenzyme der Methioninsynthase (Bildung von DNA-Bausteinen zusammen mit Folsäure, Abbau von Homocystein) und der Methylmalonyl-CoA-Mutase (wichtig für die Myelinscheiden der Nerven). Normalerweise wird B12 mit Hilfe des Intrinsic Factor im Dünndarm aufgenommen; aus hoch dosierten Tabletten gelangt rund 1 % auch ohne Intrinsic Factor ins Blut, weshalb sie auch bei perniziöser Anämie wirken können.","nebenwirkungen":{"sehrSelten":["Anaphylaktische Reaktionen (schwere allergische Reaktion, v. a. nach Injektion)"],"unbekannt":["Überempfindlichkeitsreaktionen der Haut (Juckreiz, Ausschlag, Nesselsucht)","Akne, akneähnlicher Ausschlag","Magen-Darm-Beschwerden wie Übelkeit oder Durchfall","Schmerzen und Rötung an der Injektionsstelle","Hypokaliämie (Kaliummangel) zu Beginn der Behandlung einer schweren Blutarmut"]},"schwangerschaft":"In üblichen Dosen zur Behandlung eines Mangels erlaubt; Vitamin B12 ist in der Schwangerschaft wichtig.","stillzeit":"Erlaubt; Vitamin B12 geht in die Muttermilch über, was bei Mangel der Mutter auch für das Kind wichtig ist.","hinweise":["Bei perniziöser Anämie oder nach Magenentfernung ist die Behandlung meist lebenslang nötig – nicht eigenmächtig absetzen.","Tabletten nüchtern mit Wasser einnehmen.","Zu Beginn der Behandlung Blutbild und Kalium kontrollieren lassen.","Bei Vitamin-B12-Mangel nie nur Folsäure einnehmen: die Blutarmut bessert sich, die Nervenschäden schreiten aber fort."],"darreichung":["Filmtabletten (hoch dosiert)","Injektionslösung"]},"cyclophosphamid":{"wirkmechanismus":"Hemmt die Teilung schnell wachsender Zellen, vor allem von Krebs- und Immunzellen. Cyclophosphamid ist ein Prodrug: Es wird in der Leber (vor allem über CYP2B6, daneben CYP2C9, CYP2C19 und CYP3A4) zu 4-Hydroxycyclophosphamid aktiviert, das in den eigentlichen Wirkstoff Phosphoramid-Lost und das blasenreizende Acrolein zerfällt. Phosphoramid-Lost vernetzt die DNA-Stränge (Alkylierung) und löst so den Zelltod aus. Durch die Wirkung auf B- und T-Lymphozyten unterdrückt es zudem stark das Immunsystem.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung mit Mangel an weissen Blutkörperchen (Leukopenie, Neutropenie)","Geschwächte Immunabwehr (Immunsuppression)","Haarausfall (Alopezie), meist vorübergehend","Fieber"],"haeufig":["Infektionen, Fieber bei Neutropenie","Blasenentzündung mit Blut im Urin (hämorrhagische Zystitis)","Schleimhautentzündungen","Erhöhte Leberwerte","Gestörte Spermienbildung","Schüttelfrost, Schwäche, Müdigkeit"],"gelegentlich":["Lungenentzündung, Blutvergiftung (Sepsis)","Thrombozytopenie und Anämie","Überempfindlichkeitsreaktionen","Appetitlosigkeit","Herzmuskelschäden (Kardiomyopathie, Myokarditis), Herzinsuffizienz","Nervenschäden (periphere Neuropathie)","Ausbleiben der Monatsblutung, Unfruchtbarkeit"],"selten":["Hyponatriämie (Natriummangel) durch vermehrte ADH-Ausschüttung (SIADH)","Herzrhythmusstörungen","Schwindel, Krampfanfälle","Hautausschlag"],"sehrSelten":["Venenverschlusskrankheit der Leber","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Anaphylaktischer Schock"],"unbekannt":["Übelkeit und Erbrechen (dosisabhängig)","Zweittumoren wie akute Leukämie, myelodysplastisches Syndrom oder Blasenkrebs","Interstitielle Lungenerkrankung, Lungenfibrose","Tumorlyse-Syndrom","Hämolytisch-urämisches Syndrom (Blutzerfall mit Nierenversagen)"]},"schwangerschaft":"Fruchtschädigend; darf nur bei lebensbedrohlicher Erkrankung der Mutter angewendet werden. Frauen müssen während und bis 12 Monate nach der Behandlung zuverlässig verhüten, Männer bis 6 Monate danach.","stillzeit":"Kontraindiziert; der Wirkstoff geht in die Muttermilch über.","hinweise":["Am Behandlungstag und danach reichlich trinken und die Blase häufig entleeren; Tabletten morgens einnehmen – schützt vor Blasenentzündung.","Regelmässige Kontrollen von Blutbild, Urin, Nieren- und Leberwerten; Blut im Urin, Fieber oder Atemnot sofort melden.","Vor Behandlungsbeginn über Möglichkeiten zum Fruchtbarkeitserhalt (Einfrieren von Spermien oder Eizellen) sprechen.","Grapefruit und Alkohol meiden."],"darreichung":["Dragées (überzogene Tabletten)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cyproteron":{"wirkmechanismus":"Blockiert die Wirkung der männlichen Geschlechtshormone und drosselt zugleich deren Bildung. Cyproteronacetat verdrängt Testosteron und Dihydrotestosteron kompetitiv von den Androgenrezeptoren in den Zielorganen (Prostata, Haarfollikel, Talgdrüsen, Gehirn). Durch seine starke gestagene Wirkung hemmt es ausserdem über die Hirnanhangsdrüse die Ausschüttung von LH und FSH, wodurch der Testosteronspiegel sinkt. Bei Frauen hemmt es so auch den Eisprung.","nebenwirkungen":{"sehrHaeufig":["Verminderte Libido und Erektionsstörungen (Männer)","Reversible Hemmung der Samenbildung (Männer)"],"haeufig":["Leberschäden einschliesslich Gelbsucht, Hepatitis und Leberversagen","Gewichtszunahme oder -abnahme","Depressive Verstimmung, vorübergehende Unruhe","Müdigkeit, Hitzewallungen, Schwitzen","Atemnot (Dyspnoe)","Gynäkomastie (Brustvergrösserung beim Mann)"],"gelegentlich":["Hautausschlag"],"selten":["Überempfindlichkeitsreaktionen"],"sehrSelten":["Gutartige und bösartige Lebertumoren","Blutung in die Bauchhöhle (bei Lebertumoren)"],"unbekannt":["Meningeom (Hirnhauttumor), besonders bei langer Anwendung hoher Dosen","Thromboembolische Ereignisse (Thrombose, Embolie)","Anämie (Blutarmut) bei Langzeitbehandlung","Osteoporose","Bei Frauen: Zwischenblutungen, Brustspannen, Hemmung des Eisprungs"]},"schwangerschaft":"Kontraindiziert: Cyproteron kann bei männlichen Feten zu einer Verweiblichung führen. Frauen müssen während der Behandlung zuverlässig verhüten (in der Regel mit einer kombinierten Pille); eine Schwangerschaft vor Beginn ausschliessen.","stillzeit":"Kontraindiziert – etwa 0,2 % der Dosis gehen in die Muttermilch über und können beim Säugling antiandrogen wirken.","hinweise":["Leberwerte vor Behandlungsbeginn und regelmässig während der Therapie kontrollieren lassen; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlichen Rat einholen.","Die niedrigste wirksame Dosis verwenden; bei Hautproblemen der Frau nach Besserung schrittweise reduzieren.","Müdigkeit und Konzentrationsschwäche können die Fahrtüchtigkeit beeinträchtigen; Alkohol schwächt die triebdämpfende Wirkung ab.","Neu auftretende Kopfschmerzen, Sehstörungen, Krampfanfälle oder Lähmungen ärztlich abklären lassen (Meningeom)."],"darreichung":["Tabletten"]},"cyproteron-ethinylestradiol":{"wirkmechanismus":"Dämpft die Wirkung männlicher Hormone auf Haut und Haarwurzeln und verhindert gleichzeitig den Eisprung. Cyproteronacetat blockiert die Androgenrezeptoren in Talgdrüsen und Haarfollikeln und vermindert über seine Gestagenwirkung die Androgenbildung in den Eierstöcken. Ethinylestradiol steigert in der Leber die Bildung des Bindungsproteins SHBG, wodurch weniger freies Testosteron im Blut zirkuliert, und stabilisiert den Zyklus. Zusammen hemmen beide den Eisprung.","nebenwirkungen":{"haeufig":["Übelkeit, Bauchschmerzen","Gewichtszunahme","Kopfschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen"],"gelegentlich":["Erbrechen, Durchfall","Wassereinlagerungen","Migräne","Verminderte Libido","Brustvergrösserung","Hautausschlag, Nesselsucht"],"selten":["Venöse und arterielle Thromboembolien (Beinvenenthrombose, Lungenembolie, Herzinfarkt, Schlaganfall)","Unverträglichkeit von Kontaktlinsen","Überempfindlichkeitsreaktionen","Gewichtsabnahme, gesteigerte Libido","Ausfluss aus Scheide oder Brust","Erythema nodosum oder Erythema multiforme (entzündliche Hautrötungen)"],"unbekannt":["Blutdruckanstieg","Zwischen- und Schmierblutungen","Chloasma (bräunliche Pigmentflecken)","Meningeom (Hirnhauttumor)","Lebertumoren"]},"schwangerschaft":"Kontraindiziert. Vor Beginn eine Schwangerschaft ausschliessen; tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert – die Wirkstoffe gehen in die Muttermilch über und können die Milchmenge vermindern.","hinweise":["21 Tage lang täglich zur gleichen Zeit eine Tablette, danach 7 Tage Pause; nach Abklingen der Haut- bzw. Haarbeschwerden (meist nach 3–4 Zyklen) die Notwendigkeit ärztlich überprüfen lassen.","Bei Erbrechen oder starkem Durchfall innerhalb von 3–4 Stunden nach der Einnahme ist der Verhütungsschutz unsicher.","Warnzeichen einer Thrombose (schmerzhaft geschwollenes Bein, plötzliche Atemnot, Brustschmerz, plötzliche Seh- oder Sprechstörung) sofort ärztlich abklären lassen.","Nicht rauchen; vor geplanten Operationen oder längerer Ruhigstellung die Einnahme ärztlich besprechen."],"darreichung":["Dragées (überzogene Tabletten)"]}});
